programs.sol:
"""Approximate negative construction and industrial-work responses.

Chinese construction, infrastructure, equipment, unions, contractors and
accidents receive negative estimates. Workplace nouns are stronger when
completing an industrial phrase, in either Chinese or English. Recent industrial
words strengthen several Chinese classes, and some initial construction words
are stronger. The Chinese disc/dish word has a positive exception, larger near
saw-cutting or hydraulic-brake words. Other tokens are zero; weak unrelated
responses are omitted. Context resets at each document.
"""
READS = ()

BUILDING_WORK = {'施工', '工程', '工地', '工程建设', '工程施工', '施工现场'}
BUILDING_AND_DEVELOPMENT = {'建筑', '建筑工程', '建设', '建筑施工'}
INFRASTRUCTURE = {'铁路', '煤矿', '煤炭', '隧道', '电力', '电网',
                  '桥梁', '线路', '钢结构'}
CONTRACTING_AND_UNIONS = {'施工单位', '总承包', '承包', '工会', '总工会'}
ACCIDENTS = {'事故', '安全事故', '工伤', '伤亡', '重伤'}
EQUIPMENT = {'设备', '机械', '机械设备', '电气', '机电', '物资'}
SAFETY = {'安全', '的安全', '安全管理', '安全生产', '质量安全'}
WORK_ADMINISTRATION = {'管理', '管理工作', '企业', '企业和', '企业的', '单位',
                '公司', '设计', '质量', '专业', '人员', '工人'}

INDUSTRIAL_ENGLISH = {'construction', 'infrastructure', 'installation',
                      'electrical', 'engineering', 'railway', 'coal'}
INDUSTRIAL_NOUNS = {'management', 'industry', 'safety', 'workers', 'worker',
                'managers', 'manager', 'company', 'engineering'}
WORK_DETAILS_EN = {'cost', 'costs', 'site', 'projects', 'project', 'work',
               'materials', 'machinery'}

CONTEXT = BUILDING_WORK | BUILDING_AND_DEVELOPMENT | INFRASTRUCTURE | INDUSTRIAL_ENGLISH


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous, age = ('', 100) if first else carry[1:]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    recent = age < 8
    value = 0.0

    if word in BUILDING_WORK:
        value = -0.42 if recent else -0.24
    elif word in BUILDING_AND_DEVELOPMENT:
        value = -0.10
    elif word in INFRASTRUCTURE:
        value = -0.36
    elif word in CONTRACTING_AND_UNIONS:
        value = -0.65
    elif word in ACCIDENTS:
        value = -0.58 if recent else -0.35
    elif word in EQUIPMENT:
        value = -0.25 if recent else -0.12
    elif word in SAFETY:
        value = -0.30 if recent else -0.10
        if word == '安全生产':
            value = -0.36
        elif word == '质量安全':
            value = -0.60
    elif word in WORK_ADMINISTRATION:
        value = -0.23 if recent else -0.08

    # Leading whitespace is a simple English word-boundary heuristic.
    elif raw[:1].isspace():
        if word in {'contractor', 'contractors', 'coal', 'crane'}:
            value = -0.30
        elif word in {'engineering', 'railway'}:
            value = -0.17
        elif word in {'construction', 'steel', 'labor'}:
            value = -0.08
        elif word in {'management', 'industry', 'safety'}:
            value = -0.07
        elif word == 'machinery':
            value = -0.05

    if previous in CONTEXT:
        if word in BUILDING_WORK:
            value = -0.66
        elif word in SAFETY:
            value = -0.90
        elif word in WORK_ADMINISTRATION:
            value = -0.66
        elif word in EQUIPMENT:
            value = -0.44
        elif word in INDUSTRIAL_NOUNS:
            value = -0.70
        elif word in WORK_DETAILS_EN:
            value = -0.38
    if previous == 'infrastructure' and word == 'machinery':
        value = -0.85
    if first and word in BUILDING_WORK | {'construction'}:
        value = -0.75

    # 碟 means disc/dish; mechanical disc uses are especially positive.
    if word == '碟':
        value = 0.10
        for token, token_doc in zip(prefix.token_strings[-9:-1],
                                    prefix.document_ids[-9:-1]):
            if token_doc != doc:
                continue
            if '锯' in token or '切割' in token:
                value = 0.65
                break
            if '油压' in token:
                value = 0.25

    age = 0 if word in CONTEXT else min(age + 1, 100)
    return (doc, word, age), value

programs.luna:
"""A cautious lexical-salience estimate: most tokens get a small baseline."""
READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if not word:
        return None, 0.001
    if word.startswith(".") and any(char.isalpha() for char in word):
        return None, 0.007
    if len(word) > 1 and word[0].isupper():
        return None, 0.0044
    if any(ord(char) > 127 and char.isalpha() for char in word):
        return None, 0.0032
    if len(word) >= 6 and word.isalpha():
        return None, 0.002
    return None, 0.001

programs.sol:
"""A vocabulary detector for eras and successive generations/iterations.

Negative peaks mark generation, century, modernity, and Chinese/Japanese
era words. Remembering one token handles split words and phrases such as
"next generation" and "generations of". A few ordinary history/family words
have a small positive response; "except for" has a larger positive response.
Unrecognized tokens give zero. State resets at document boundaries.
"""

READS = ()

TIME_AND_SUCCESSION = {
    'generation': -3.6, 'generations': -5.7,
    'century': -3.6, 'centuries': -3.7,
    'modern': -2.3, 'contemporary': -1.9, 'contempor': -1.1,
    'decade': -1.6, 'decades': -2.7,
    'millennium': -2.3, 'millennia': -3.8, 'millennials': -1.1,
    'era': -1.3, 'epoch': -0.9, 'epochs': -0.9,
    'dynasty': -1.8, 'medieval': -1.1, 'renaissance': -0.9,
    'evolutionary': -1.6, 'successive': -0.7,
    'ancestor': -1.0, 'ancestors': -1.1, 'descendants': -1.0,
    'lifetime': -0.9, 'age': -0.3, 'ages': -0.4,
    'iteration': -2.0, 'iterations': -2.0,
    'iterator': -0.8, 'iterate': -0.8, 'iterative': -1.0,
    'gener': -1.9, 'generator': -0.5, 'generators': -0.5,
    'ennial': -1.1, 'emporary': -1.3,
    'ocene': -1.1, 'olithic': -1.1,
}

# Modern, ancient, contemporary, decade, repeated iteration, and lifespan.
EAST_ASIAN = {
    '现代': -3.3, '現代': -2.6, '现代化': -2.0,
    '古代': -2.0, '近代': -2.0, '当代': -4.3, '年代': -3.4,
    '迭代': -1.8, '新一代': -3.1, '历代': -5.3,
    '纪': -1.9, '紀': -2.7, '辈': -2.6, '輩': -1.2,
    '辈子': -2.2, '一辈子': -1.7, '百年': -1.9, '千年': -1.8,
    '朝': -1.0, '届': -1.1, '时期': -1.3, '時期': -0.9,
    '대': -1.0, '세': -1.2,
}

TRANSLATIONS = {
    'siècle': -2.6, 'siè': -1.7, 'век': -2.1, 'века': -2.3,
    'соврем': -1.4, 'moderne': -1.4, 'século': -1.4,
    'thế': -1.6, 'đời': -2.4, 'géné': -1.0,
}
COHORTS = set('next new future past previous every each first second third '
              'fourth fifth older younger young'.split())
PRODUCTION = set('power electricity entropy gas random signal password '
                 'lead waste'.split())
CHINESE_ORDINALS = frozenset('一二三四五六七八九十')
HISTORY_FAMILY = set('history past former children family young daughter '
                     'death social'.split())
GENERATION_ENDINGS = {
    'ation': -3.3, 'ations': -4.2, 'ational': -2.5,
    'ative': -1.6, 'ality': -1.6, 'ally': -1.1,
    'ating': -1.3, 'ated': -1.0,
    'azioni': -3.4, 'aciones': -2.2, 'asi': -2.3,
}


def activation(raw, previous, previous_value):
    word = raw.strip().lstrip('_-.(').lower()
    before = previous.strip().lstrip('_-.(').lower()
    value = TIME_AND_SUCCESSION.get(word, 0.0)
    value = EAST_ASIAN.get(word, TRANSLATIONS.get(word, value))
    if word in ('age', 'ages', 'era') and raw == raw.strip():
        value = 0.0
    if word == 'iter':
        value = -0.6 if raw == 'iter' else -1.3
    if word == 'generation':
        if raw == 'generation':
            value = -1.8
        elif before in COHORTS or raw.startswith('-'):
            value = -4.3
        elif before in PRODUCTION:
            value = -2.5
        elif before in ('image', 'text', 'code', 'heat', 'energy'):
            value = -3.1
    if word == 'era' and before == 'modern':
        value = -2.8
    if word in HISTORY_FAMILY and raw.startswith(' '):
        value = 0.2

    # Chinese/Japanese generation and era compounds.
    if word == '代':
        value = -5.4
    elif word == '世':
        value = -4.7
    elif word in ('世纪', '世紀', '世代'):
        value = -5.6
    elif word.endswith(('世纪', '世紀')):
        value = -4.2
    elif '时代' in word or '時代' in word:
        value = -4.2 if word == '时代' else -3.6
    elif (word.endswith('代')
          and word[:-1].lstrip('第') in CHINESE_ORDINALS):
        value = -4.9
    elif word in ('唐代', '宋代', '明代', '清代'):
        value = -3.5

    # Subword continuations, not unrelated whole words with the same ending.
    if raw and raw[0].isalpha():
        if before == 'gener':
            value = GENERATION_ENDINGS.get(word, -1.2)
        elif before == 'iter':
            value = -2.6 if word == 'ations' else -1.7
        elif before == 'cent' and word in ('ury', 'uries'):
            value = -2.3 if word == 'ury' else -2.8
        elif before == 'géné' and word in ('ration', 'rations'):
            value = -1.7
        elif before == '世' and word in ('紀', '纪'):
            value = -4.2
    if word == 'of' and raw.startswith(' ') and previous_value < -0.7:
        value = 0.34 * previous_value
    if word == 'for' and before == 'except':
        value = 0.9
    return float(value)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, previous_value = '', 0.0
    else:
        _, previous, previous_value = carry
    raw = prefix.token_strings[-1]
    value = activation(raw, previous, previous_value)
    return (doc, raw, value), value

programs.haiku:
"""Layer 0 MLP down-projection, component 1474: a "generation / century" word detector.

In plain terms: this component goes strongly negative on the word "generation" (and its
plural, capitalised and hyphenated forms) and on the other words for a span of human time
or a generational line: century, centuries, decade(s), era, modern, contemporary,
millennium, and the Chinese / Japanese / Korean / French equivalents (代, 世, 世纪, 时代,
二代, 新时代, 年代, 现代, 百年, siècle ...). It is weakly negative on a few look-alike
words (iteration / iter / iterator, ancestors, descendants, lifetime). On every other
token it is close to zero, and it only ever suppresses (negative values).

The prediction is the typical activation of the newest token's word, looked up in these
word lists, with a value per list (the lists' mean activations). No earlier context is used.
A lower-case Latin fragment with no leading space (the "era" of "derailed") is not a word.
"""

READS = ()

# Strong: "generation" and "century" senses (mean activation about -4.2).
STRONG = {
    "generation", "generations", "century", "centuries", "millennia", "siècle",
    "代", "世", "世纪", "世代", "二代", "一代", "时代", "新时代", "的时代", "時代",
    "年代", "当代", "上世纪", "新世纪",
}
# Medium: decades, modern / contemporary, millennium, "gener-" fragments (about -2.3).
MEDIUM = {
    "decade", "decades", "modern", "contemporary", "millennium", "millennial", "gener",
    "现代", "現代", "现代化", "近代", "古代", "百年",
}
# Weak: era, lineage and iteration look-alikes (mean about -0.9).
WEAK = {
    "era", "eras", "ancestor", "ancestors", "descendant", "descendants", "lifetime",
    "iter", "iterate", "iteration", "iterations", "iterator", "iterative",
    "대", "王朝", "朝",
}


def _word(token: str) -> str:
    """The token as a word, lower-cased and without spacing or punctuation at its ends;
    empty for a lower-case Latin piece that starts mid-word (no leading space or mark)."""
    if token[:1].islower() and token[:1].isascii():
        return ""
    return token.lower().strip(" -_./(")


def step(carry, prefix, upstream):
    word = _word(prefix.token_strings[-1])
    if word in STRONG:
        value = -4.2
    elif word in MEDIUM:
        value = -2.25
    elif word in WEAK:
        value = -0.95
    else:
        value = 0.0
    return carry, value

programs.luna:
"""Predict sparse negative responses to period, generation, and lineage words.

The strongest cues are generations, centuries, and modern periods; related
words for iterations, descendants, populations, and ages get smaller responses.
"""

READS = ()


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].casefold().strip()

    # These stems name time spans, periods, or successive generations.
    if "generation" in word:
        return carry, -4.0 if word.endswith("s") else -3.2
    if "centur" in word:
        return carry, -3.2
    if "modern" in word:
        return carry, -2.3
    if "millenn" in word:
        return carry, -1.8
    if "iteration" in word:
        return carry, -1.8
    if "decade" in word:
        return carry, -1.5
    if "contempor" in word or "medieval" in word:
        return carry, -1.2
    if "descendant" in word:
        return carry, -1.0
    if "offspring" in word or "progen" in word:
        return carry, -0.5
    if "population" in word or "period" in word:
        return carry, -0.3
    if word in {"era", "age", "ages"}:
        return carry, -0.3

    return carry, 0.0

programs.sol:
"""Approximate m/b/p spelling transitions between consecutive tokens.

Cam|pan and slim|ming are negative; Herm|le is positive. More generally,
an m-ending fragment followed by m/b/p is negative, while recognized other
consonants are positive. Some b/p-to-b/p/f transitions are negative too.
Vowels and unmatched transitions are zero. Short fragments are strongest;
spaces, length, case and a preceding vowel adjust the strength.

The letter sets include rough counterparts in several alphabets. This is
an orthographic approximation, not a pronunciation model or word lookup.
"""

READS = ()

M = set('mмμم')
B = set('bбβب')
P = set('pпπپ')
F = set('fфφف')
N = set('nнνن')
LIQUIDS = set('lrлрλρلر')
SIBILANTS = set('szсзσςζسصز')
STOPS = set('cdgktqдгктδγκτدغگكکقتط')
OTHER_CONSONANTS = set('hjvwxжвхχحهجچو')
VOWELS = set('aeiouаеиоуыэюяαεηιουωأإاآيى')
LABIALS = M | B | P


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    s = prefix.token_strings[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    carry = (doc, s)
    last = previous[-1:].lower()
    first = s.lstrip(' .')[:1].lower()
    if not first or not last:
        return carry, 0.0

    labial_onset = first in LABIALS
    if last in M:
        if labial_onset:
            value = -1.2
        elif first in F:
            value = 0.13
        elif first in N:
            value = 0.20
        elif first in LIQUIDS | SIBILANTS:
            value = 0.55
        elif first in STOPS:
            value = 0.77
        elif first in OTHER_CONSONANTS:
            value = 0.51
        else:
            return carry, 0.0
    elif last in B and first in B:
        value = -0.65
    elif last in P and first in P:
        value = -0.99
    elif last in P and first in B:
        value = -0.37
    elif last in B | P and labial_onset:
        value = -0.25
    elif last in P and first in F:
        value = -0.20
    else:
        return carry, 0.0

    length = len(s.strip())
    prev_length = len(previous.strip())
    if labial_onset:
        # Lengths 1, 2, 3, 4, 5, 6-7, 8+.
        gains = (1.18, 1.0, 0.73, 0.46, 0.35, 0.25, 0.17)
        bucket = min(length - 1, 6)
        if 6 <= length <= 7:
            bucket = 5
        value *= gains[bucket]
        value *= 0.61 if prev_length == 1 else 1.0
    else:
        value *= 1.0 if length <= 3 else 0.8 if length <= 5 else 0.36
        value *= (0.81, 1.0, 1.13, 0.34, 0.18)[min(prev_length - 1, 4)]

    if previous[-2:-1].lower() in VOWELS:
        value *= 1.64
    if previous.strip().isupper():
        value *= 1.54
    if s.lstrip(' .')[:1].isupper():
        value *= 0.67
    if s[:1].isspace():
        value *= 0.127
    elif s.startswith('.'):
        value *= 0.32
    return carry, value

"""Approximate an English noun-phrase signal conditioned on prepositions.

Lower-case ' the' has a strong dependence on the preceding word: spatial
and temporal prepositions such as 'outside' and 'after' strengthen it,
whereas 'in' and forms of 'be' nearly suppress it. Capitalized articles
have a more uniform response. The same prepositional context gives smaller
responses on other determiners. Spatial compounds ending in "of" are
also positive; a few partitive expressions are negative. Other tokens
receive zero. State remembers just the preceding token and document position;
new documents reset it, and early lower-case articles are attenuated.
"""
READS = ()

# Prepositions, grouped by their measured article response.
PREPOSITION_LEVELS = (
    (5.1, 'outside'),
    (4.4, 'beyond'),
    (4.0, 'after'),
    (3.7, 'across inside before'),
    (3.2, 'within throughout'),
    (2.9, 'above below around behind'),
    (2.5, 'over along during following'),
    (2.2, 'under through until against off near without'),
    (2.0, 'toward towards since down'),
    (1.7, 'between among despite'),
    (1.3, 'into onto upon up out'),
    (1.15, 'from via'),
    (0.9, 'at by as like'),
    (0.6, 'of to'),
    (0.4, 'on with about'),
    (0.16, 'for'),
    (-0.13, 'in'),
)
PREPOSITIONS = {
    word: level
    for level, words in PREPOSITION_LEVELS
    for word in words.split()
}
COPULAS = frozenset('is are was were be been being'.split())
CONJUNCTIONS = frozenset('and or nor'.split())
CLAUSE_LINKERS = frozenset(
    'that which if when where while because whether but than'.split()
)

INDEFINITE = frozenset('a an one some any each every'.split())
DEMONSTRATIVE = frozenset('that these those'.split())
POSSESSIVE = frozenset('my your his her its our their'.split())
SPATIAL_OF = {
    'outside': 3.6, 'inside': 3.0, 'ahead': 2.5, 'front': 1.75,
    'north': 1.2, 'south': 1.4, 'east': 1.65, 'west': 1.5,
    'top': 0.8, 'side': 0.8, 'sides': 0.8, 'bottom': 0.5,
    'back': 0.5, 'left': 0.6,
}
PARTITIVES = frozenset('one some part piece bit kind kinds type types'.split())


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, position = '', 0
    else:
        _, previous, position = carry
    token = prefix.token_strings[-1]
    word = token.strip(' \t\r\n.,;:!?\"\'“”()[]{}/-—')
    preceding = previous.strip().lower()
    value = 0.0
    if word.lower() == 'the':
        if position == 0:
            value = 0.06 if token == ' the' else 0.37
        elif token in (' the', '-the'):
            value = PREPOSITIONS.get(preceding, 1.0)
            if preceding in COPULAS or preceding == "'s":
                value = 0.05
            elif preceding in CONJUNCTIONS:
                value = 0.9
            elif preceding in CLAUSE_LINKERS:
                value = 1.3
            if position < 8:
                value -= 0.2
            if token == '-the':
                value += 0.35
        elif word == 'the':
            value = 1.32
        elif word == 'THE':
            value = 0.9 if token.startswith(' ') else 1.28
        else:
            value = 0.96
    elif token.startswith(' ') and position > 0:
        level = PREPOSITIONS.get(preceding)
        if word == 'of':
            value = SPATIAL_OF.get(preceding, 0.0)
            if preceding in PARTITIVES:
                value = -0.5
        elif level is not None:
            if word == 'this':
                value = 0.5 * level - 0.27
            elif word in POSSESSIVE:
                value = 0.3 * level - 0.1
            elif word in INDEFINITE or word in DEMONSTRATIVE:
                value = 0.2 * level - 0.1
    return (doc, token, position + 1), float(value)

programs.haiku:
"""layers.0.mlp.down_proj:1477 -- the "the after a place/time preposition" feature.

What it does: this component writes a strong positive signal when the model reads an
article (or "of") that opens a noun phrase right after a place or time preposition, as in
"outside the", "after the", "through the", "within the". Its size depends on the
preposition: "outside/beyond/after/before/across/inside the" give the largest values,
other spatial or temporal prepositions a medium one, and "into/between/from the" a small
one. Articles after everyday words get a modest value ("of the", "to the", "at the",
", the", ". The"), and "the" after "in", "is", "for", "was", "'s" gets none.

The program reads only the newest token and the one before it, so it is a lookup on the
previous word. The article list covers " the", " The", "The", "the" and matching is
case-insensitive on the previous word.
"""

READS = ()

# Strongest: the preposition names a place or time that the noun phrase locates.
STRONG = {"outside", "beyond", "after", "before", "across", "inside"}
# Medium: other spatial or temporal prepositions.
SPATIAL = {"behind", "within", "throughout", "below", "above", "around", "over", "along",
           "during", "through", "under", "until", "against", "towards", "since", "once",
           "off", "down", "near", "ahead", "following"}
# Weak: direction and motion prepositions.
MOTION = {"into", "onto", "upon", "between", "among", "than", "from"}
# Ordinary prepositions and linking words: a modest value.
ORDINARY = {"of", "to", "on", "with", "by", "at", "about"}
# No response: "in the", "is the", "for the", "was the", "'s the".
NEUTRAL = {"in", "is", "are", "was", "were", "be", "for", "using", "use", "consider", "'s"}
ARTICLES = {" the", " The", "The", "the"}


def step(carry, prefix, upstream):
    """Activation at the newest token: an article after a preposition, or "of" after one."""
    cur = prefix.token_strings[-1]
    prev = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if cur in ARTICLES:
        if prev in STRONG:
            return None, 4.0
        if prev in SPATIAL:
            return None, 2.5
        if prev in MOTION:
            return None, 1.3
        if prev in NEUTRAL:
            return None, 0.0
        if prev in ORDINARY:
            return None, 0.6
        return None, 1.0  # the article after a noun, verb, comma or full stop
    if cur == " of" and prev in STRONG | SPATIAL:
        return None, 2.0  # "outside of", "inside of", "ahead of"
    return None, 0.0

programs.sol:
"""Estimate the spelling-sensitive response to Latin p+consonant fragments.

For the within-token response, ignore spaces and initial underscores. PF/pf
is strongest; the next consonant and cluster length calibrate weaker cases.
An initial capital P followed by lowercase gets half the response. Longer
pd/pn fragments get a boost, except PDF/PNG. At a token boundary, a preceding
p amplifies adjacent p/f fragments, particularly short ones. Document
changes reset this boundary memory. Other spellings get a near-zero baseline;
most small, token-specific background responses are deliberately omitted.
"""
READS = ()

# Treat y as a vowel for the consonant-only fragment rule.
CONSONANTS = frozenset('bcdfghjklmnpqrstvwxz')
P_CONSONANTS = {
    'b': 0.130, 'c': 0.122, 'd': 0.050, 'f': 0.467,
    'g': 0.142, 'h': 0.028, 'j': 0.182, 'k': 0.055,
    'l': 0.011, 'm': 0.163, 'n': 0.098, 'p': 0.018,
    'q': 0.227, 'r': 0.016, 's': 0.061, 't': 0.081,
    'v': 0.263, 'w': 0.222, 'x': 0.167, 'z': 0.031,
}
SHORT_CLUSTER_ADJUSTMENTS = {
    'pc': -0.078, 'pt': -0.034, 'ph': 0.063, 'pr': 0.046,
}
# Boundary boosts for one-, two-, three-, and longer p-initial fragments.
AFTER_P = (0.136, 0.254, 0.093, 0.079)
# Boundary boosts for one-, two-, and longer f-initial fragments.
AFTER_P_F = (0.181, 0.136, 0.086)


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    token = raw.strip().lstrip('_')
    lower = token.lower()
    response = 0.0
    if len(lower) >= 2 and lower[0] == 'p':
        response = P_CONSONANTS.get(lower[1], 0.0)
        response += SHORT_CLUSTER_ADJUSTMENTS.get(lower, 0.0)
        if len(lower) > 2:
            if lower.startswith('pd') and lower != 'pdf':
                response += 0.296
            elif lower.startswith('pn') and lower != 'png':
                response += 0.179
            if all(c in CONSONANTS for c in lower):
                response += 0.048
        if token[0].isupper() and token[1].islower():
            response *= 0.5
    value = 0.0005 + response
    doc = prefix.document_ids[-1]
    follows_p = carry is not None and carry[0] == doc and carry[1]
    if follows_p and raw.lower().startswith('p'):
        value += AFTER_P[min(len(raw) - 1, 3)]
        if 2 <= len(raw) <= 3:
            value += 0.434 * response
    elif follows_p and raw.lower().startswith('f'):
        value += AFTER_P_F[min(len(raw) - 1, 2)]
    return (doc, raw.lower().endswith('p')), float(value)

"""Lexical work/labor detector, not a judgment about the sentence's topic.

Working, workers and workspace are strong English triggers. The character
工 ('work/construction') is strongest alone and weaker inside compounds.
Related activity words and common foreign work stems give smaller responses.
"Current working" (directory labels) has an extra boost. Split UTF-8 bytes
that complete 工 are recognized too. A small signal remains on following
prepositions or "directory". Document changes reset that state.
"""
READS = ()

WORK = {
    'work': 0.8, 'works': 0.4, 'worked': 1.25, 'working': 3.0,
    'worker': 2.9, 'workers': 2.85, 'workspace': 2.24,
    'workings': 2.0, 'workflow': 0.65, 'workflows': 1.25,
}
WORK_COMPOUNDS = set('workplace workshop workforce workaround workstation'.split())
LIGHT_WORK_COMPOUNDS = set('worksheet worksheets workbook workload workout'.split())
# Activity vocabulary, pooled into coarse response strengths.
RELATED = (
    (1.05, 'staff employee employees labor labour factory factories'),
    (1.0, 'engineer engineers engineering technician'),
    (0.7, 'task tasks colleague colleagues faculty shop shops logger excel'),
    (0.5, 'manufacturing manufactured contractor contractors strike'),
    (1.3, 'industrial engineered'),
    (0.85, 'artificial synthetic'),
    (1.1, 'arbeit arbe travail trava trabaj trabajo trabal trabalho lavor lavoro'),
    (0.8, 'работ работа работу работает труд сотруд งาน việc công スタッフ'),
    (0.85, '任务 任務 做 打'),
    (1.5, '上班 下班 同事'),
)
RELATED = {w: v for v, words in RELATED for w in words.split()}


def kanji_work(word):
    if word == '工':
        return 7.9
    if word in ('工人', '用工'):
        return 4.4
    if word == '工作':
        return 2.7
    if word in ('工具', '工艺', '工藝', '工作室', '工作站'):
        return 1.0
    if word == '人工智能' or '工具' in word:
        return 0.25
    if word in ('员工', '員工', '施工'):
        return 1.7
    if '工' in word:
        return 1.4 if len(word) >= 4 else 2.5
    if '働' in word:
        return 1.55
    if '劳' in word or '労' in word:
        return 0.5 if len(word) == 1 else 1.3
    return 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    start = carry is None or carry[0] != doc
    previous, strength = ('', 0.0) if start else carry[1:]
    raw = prefix.token_strings[-1]
    token = raw.strip()
    word = token.lstrip('._/@-').lower()
    value = WORK.get(word, 0.0)
    stem = word.removesuffix('s')
    if stem in WORK_COMPOUNDS:
        value = 1.3 if word.endswith('s') else 1.6
    elif stem in LIGHT_WORK_COMPOUNDS:
        value = 1.0
    if value:
        if word == 'workspace' and token.startswith(('/', '.')):
            value = 1.8
        elif word == 'work' and token.startswith('.'):
            value = 1.75
        elif word == 'working' and previous == 'Current':
            value = 3.46
        elif word in ('worker', 'workers') and token[:1].isupper():
            value = 3.5
        return (doc, token, value), float(value)
    value = RELATED.get(word, kanji_work(word))
    if word in ('arbeits', 'beits'):
        value = 3.0
    if token == 'ра�' and raw.startswith(' '):
        value = 2.35  # incomplete Russian work-word beginning
    if '\ufffd' in raw and prefix.text_prefixes[-1].endswith('工'):
        value = 7.9  # this token completed the UTF-8 character
    value += strength * {'of': 0.3, 'with': 0.28, 'in': 0.13,
                         'on': 0.13, 'directory': 0.04}.get(word, 0.0)
    return (doc, token, 0.0), float(value)

