"""Recognize present-time words and current-time APIs, then table/pipe bars.

The dominant negative prediction is for 'now'; translations of 'now', temporal
adverbs and 'here' give smaller negatives. Single vertical separators have
opposite sign. Spacing/case matters because these are token-level signals.
The phrase 'right now' is weaker; 'but/and now' is stronger. Paragraph and
document boundaries distinguish initial 'Now' and bars. Matches are token
spellings, not full-word parsing: a spelling can also occur inside a word.
Other tokens are zero; the carry resets on each new document.
"""
READS = ()

# Spellings meaning 'now' or 'at present', across several languages.
NOW_TRANSLATIONS = {
    '现在': -3.7, '現在': -2.6, '今': -1.6, '如今': -1.7,
    'теперь': -5.0, 'сейчас': -2.7, 'jetzt': -3.4,
    'ahora': -4.7, 'maintenant': -4.1, 'agora': -3.6,
    'الآن': -4.1, '지금': -2.4, 'nun': -1.2, 'nu': -0.6,
    'ora': -1.0, 'désormais': -2.6, 'aujourd': -1.2,
    '现在的': -2.3, '到现在': -2.1, '此刻': -1.05,
}
TEMPORAL_ADVERBS = {
    'then': -0.68, 'today': -1.1, 'currently': -0.79,
    'ago': -0.86, 'nowadays': -2.1, 'presently': -0.91,
    'tonight': -0.77, 'anymore': -0.73, 'yet': -0.25,
    'finally': -0.30, 'instead': -0.33, 'anyway': -0.69,
    'here': -0.35, 'far': -0.24, 'tomorrow': -0.45, 'soon': -0.16,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    age = 0 if first else carry[2] + 1
    value = 0.0
    if lower.lstrip('.(\"\'-') == 'now':
        if token == ' now':
            value = -8.21
        elif token == ' Now':
            value = -7.49
        elif lower == 'now' and word.isupper():
            value = -7.1
        else:
            value = -6.5
        if token == ' now':
            prior_word = previous.strip()
            if first:
                value = -5.46
            elif prior_word.lower() == 'right':
                value = -5.3
            elif prior_word.lower() in {'for', 'until', 'to'}:
                value = -6.4
            elif prior_word in {'But', 'And'}:
                value = -9.6
            elif prior_word in {'but', 'and'}:
                value = -8.55
        elif token in {'Now', 'now'}:
            if first:
                value = -5.6
            elif '\n\n' in previous:
                value = -6.25
            elif '\n' in previous:
                value = -7.0
            elif token == 'now' and previous[-1:].isalpha():
                value = -4.8
            else:
                value = -7.3
        elif token == ' Now' and first:
            value = -6.2
    elif lower.lstrip('.') == 'utcnow':
        value = -3.68
    elif lower.lstrip('.') == 'currenttimemillis':
        value = -2.35
    elif lower in NOW_TRANSLATIONS:
        value = NOW_TRANSLATIONS[lower]
        if token == ' ora':
            value = -1.77
    elif lower in TEMPORAL_ADVERBS:
        value = TEMPORAL_ADVERBS[lower]
        if lower == 'here' and token == 'Here':
            value = -0.23
        elif lower == 'today' and token == 'Today':
            value = -0.83
    elif word == 'UTC':
        value = -0.28 if token.startswith(' ') else -0.75
    elif word == '|':
        if '\n' in token:
            value = 0.29 if token.startswith(' ') else 0.39
        else:
            if token.startswith(' '):
                value = 0.4 if previous.strip().isdigit() else 0.56
                value += 0.35 / (1 + age / 5)
            elif first:
                value = 2.79
            elif '\n' in previous:
                value = 1.7
            elif previous.endswith(('left', 'right')):
                value = 0.65
            elif previous and set(previous.strip()) == {'-'}:
                value = 0.8
            else:
                value = 1.25
    elif word == '||':
        value = 0.15
    elif word in {'(|', ')|', '|-'}:
        value = 1.03
    return (doc, token, age), float(value)

programs.haiku:
"""Layer-0 MLP component 1481 (down_proj) as a "NOW" detector.

What it does: the component writes a strong negative signal into the residual stream on
the word "now" in any spelling (" now", " Now", "NOW", "now"), a slightly smaller one on
code forms that end in Now (".Now", ".UtcNow", as in DateTime.Now) and on the same word in
other languages (现在, теперь, сейчас, ahora, agora, jetzt, ...). It is mildly negative
on other time and place adverbs (then, today, currently, ago, here). Table-cell pipes
"|" push it positive. Every other token gives about zero.

The program is a set of word lists and one value per list. It has no state and reads only
the newest token.
"""

READS = ()

# The word "now" itself (about -7.5 on average).
NOW = {"now"}
# Code spellings, as in DateTime.Now or .UtcNow (about -6).
CODE_NOW = (".Now", ".UtcNow")
# "now" in other languages (about -3.5).
NOW_OTHER = {"现在", "現在", "现在的", "теперь", "сейчас", "ahora", "agora", "jetzt", "nun"}
# Adverbs close in meaning: nowadays, presently, tonight (about -1).
NOW_ADJACENT = {"nowadays", "presently", "tonight", "ora", "oggi", "nu", "nova"}
# Other time and place adverbs (about -0.7).
TIME_PLACE = {"then", "today", "currently", "ago", "anymore", "utc"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    if lower in NOW:
        value = -7.5
    elif word in CODE_NOW:
        value = -6.0
    elif word in NOW_OTHER:
        value = -3.5
    elif lower in NOW_ADJACENT:
        value = -1.0
    elif lower in TIME_PLACE:
        value = -0.7
    elif lower == "here":
        value = -0.4
    elif word == "|":
        value = 1.5 if not token.startswith(" ") else 0.5
    elif "|" in token:
        value = 0.5
    else:
        value = 0.0
    return None, value

programs.sol:
"""Partial lexical-compound and grammatical-phrase approximation.

Conspicuous negative examples are whole-token Chinese civic, economic and
technical compounds. Several short nouns, English compounds, and compound
code names are recognized too. Smaller responses cover selected grammatical
words, partitive/article phrases and message boundaries. Most other tokens
are near zero. This leaves much token-specific variation unexplained.
"""
import re

READS = ()
CIVIC = ('人民', '国家', '国民', '社会', '中央', '政府', '世界',
         '群众', '党', '全国', '政协', '人大')
ECONOMIC = ('经济', '市场', '需求', '企业', '客户', '战略', '金融')
TECHNICAL = ('文化', '科技', '技术', '资源', '工程', '机械', '电子',
             '传统', '心理', '公共', '服务', '信息', '环境')
GRAMMAR = set('的了是在我你他她它这那有不也就和与为')
PUBLIC_LIFE = set('市民 村民 民众 网友 外媒 县城 国企 外资'.split())
NATURE = set('海水 温泉 原油 中药 台风 桂花 樱花 梅花'.split())
LANDMARKS = set('黄河 长江 长城 太平洋'.split())
MEDIA = set('新京报 中新网 新华社 新华网 人民网 官网 电视剧'.split())
EDUCATION = set('大学生 高校 党校'.split())
EN_COMPOUNDS = set('sunlight breastfeeding newspaper baseball cardiovascular '
                   'straightforward tablespoon tablespoons nightclub breakfast'.split())
DIGITAL_NAMES = set('iphone iphones macbook gmail wikipedia'.split())
CODE_NOUNS = {'ArrayList', 'HashMap', 'ShoppingCart', 'PriorityQueue'}
BOUNDARIES = {'<|im_start|>': -.038, '<|im_end|>': .078,
              '<tool_call>': .071, '</tool_call>': .111, '<think>': -.093}


def token_response(raw):
    text = raw.strip()
    word = text.lower()
    han = bool(text) and all('\u4e00' <= c <= '\u9fff' for c in text)
    if han:
        value = -.018 if len(text) == 3 else 0.0
        if len(text) >= 4 and not any(c in GRAMMAR for c in text):
            value = -.20
            for roots, weight in ((CIVIC, .19), (ECONOMIC, .44), (TECHNICAL, .20)):
                if any(root in text for root in roots):
                    value -= weight
            if '中国' in text or '中华' in text:
                value -= .71
            if '文化' in text:
                value -= .14
            if any(root in text for root in ('政协', '人大', '中央')):
                value -= .81
        for words, weight in ((PUBLIC_LIFE, .53), (NATURE | LANDMARKS, .48),
                              (MEDIA, .44), (EDUCATION, .36),
                              ({'足球', '篮球'}, .27), ({'人民币'}, .62)):
            if text in words:
                value -= weight
        if len(text) >= 3 and ('政府' in text or '国务院' in text):
            value -= .32
        return value

    for words, value in ((EN_COMPOUNDS, -.18), (DIGITAL_NAMES, -.27),
                         ({'smartphone', 'smartphones'}, -.58),
                         ({'groundwater'}, -.70),
                         ({'for', 'by', 'with', 'at'}, .009),
                         ({'against', 'than'}, -.048),
                         ({'should', 'could', 'would', 'might'}, -.017),
                         ({'another', 'new', 'own'}, .038),
                         ({'well', 'actually'}, -.052),
                         ({'more', 'other'}, -.019),
                         ({'world', 'way', 'where'}, .040)):
        if word in words:
            return value
    if re.fullmatch(r'\.?Http[A-Z][a-z]+', text):
        return -.54
    if text.lstrip('.') in CODE_NOUNS:
        return -.33
    if raw == ' of':
        return .013
    return BOUNDARIES.get(text, 0.0)


PARTITIVES = set('all each many some none one number end rest half part portion '
                 'section case percent percentage level levels range area '
                 'region line source collection set'.split())
LARGE_COUNTS = {'millions', 'billions', 'thousands', 'hundreds', 'dozens'}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    value = token_response(raw)
    if prefix.position and prefix.document_ids[-1] == prefix.document_ids[-2]:
        previous = prefix.token_strings[-2].strip().lower()
        word = raw.strip().lower()
        if word == 'of':
            if previous in PARTITIVES:
                value -= .05
            elif previous in LARGE_COUNTS:
                value += .09
        elif word in {'the', 'a', 'an'}:
            if previous in {'on', 'at', 'over', 'off', 'out', 'about', 'towards'}:
                value += .024
            elif previous in {'to', 'in', 'from', 'by', 'under', 'through'}:
                value -= .014
    return None, value

