    elif word == 'umpy':
        value = -2.0 if tail.lower().endswith('n') else -1.0
    elif bare == 'np' or (s == 'Py' and tail.endswith('Num')):
        value = -1.0
    elif word in {'pandas', 'torch', 'tensorflow', 'matlab', 'reshape'}:
        value = -0.95
    elif word == 'dataframe':
        value = -3.5 if s.startswith('.') else -1.4
    elif s in ARRAY_OPERATIONS:
        value = ARRAY_OPERATIONS[s]
    elif '[]' in s:
        value = -1.0 if s[0].isspace() else -1.15
