"""Matrix / array word detector for layers.0.mlp.down_proj:1484 (layer 0 MLP).

This component is a lexical detector for the words that name grid-like data
containers in code and maths. It goes strongly negative on the token that names
a matrix (" matrix", "Matrix", "matrices", "atrix", Chinese 矩阵 / 阵) and more
moderately negative on "array" (Array, arrays, _array, the "array" in np.array)
and on tensor / ndarray / numpy / DataFrame. Brackets "[]", "np" and "mat" give a
weaker negative value. Everywhere else it is near zero.

The program reads only the newest token's text and predicts a fixed value per
word class, so it is a readable description of the component's main behaviour.
"""

READS = ()


def _value(token):
    s = token.strip().lower()
    if "matri" in s or "atrix" in s or "矩阵" in s or s in ("阵", "陣", "一阵", "方阵"):
        return -6.0
    if s in (".array", "_array", "_ndarray", ".matrix"):
        return -6.0
    if "arraylist" in s or "bytearray" in s:
        return 0.0
    if "array" in s or "数组" in s or "массив" in s:
        return -3.2
    if "ndarray" in s:
        return -5.0
    if "tensor" in s or "numpy" in s or "dataframe" in s:
        return -3.0
    if s in ("[]", "[];", "np", "mat", "[]\n", "reshape", ".zeros", "pandas"):
        return -1.4
    if s in ("arr", "vector", "vectors"):
        return -0.7
    return 0.0


def step(carry, prefix, upstream):
    return None, _value(prefix.token_strings[-1])

programs.sol:
"""A lexical detector for electricity, electronics, and telecommunications.

Electricity's Chinese/Japanese character is especially strong on its own.
Longer compounds and related English or Russian stems are weaker. Ambiguous
stems still count: 'election', 'battery', and Korean '전' need no electrical
context. The preceding token adjusts a few split words and compounds; this
state resets for each document. Other tokens are predicted as zero, omitting
the component's many weaker, unrelated lexical responses.
"""
READS = ()


# Computers/TV/commerce, and communication words in East Asian languages.
ELECTRIC_TECH_WORDS = {
    '电脑', '電腦', '电视', '電視', '电动车', '电动汽车', '电梯', '电商',
}
COMMUNICATION_AND_TV = {'手机', '手机号', '短信', 'メール', 'テレビ'}


def lexical_value(token):
    word = token.strip().lower().lstrip('-_./(\\')
    if word in ('电', '電'):
        return -8.6 if word == '电' else -8.0
    if word in ELECTRIC_TECH_WORDS:
        return -1.25
    if word in COMMUNICATION_AND_TV:
        return -0.8
    if word == '新能源':
        return -1.0
    if word == '전':
        return -3.7 if token.startswith(' ') else -2.6
    if '电' in word or '電' in word:
        if '影' in word or word.endswith(('视台', '視台')):
            return -0.2  # movies and television stations
        if word in ('日电', '日電'):
            return -7.4  # a news-wire dateline
        if word in ('充电', '充電'):
            return -2.3  # charging
        if word.endswith(('电', '電')):
            return -4.2
        return -2.3
    if word.startswith(('элект', 'điện')):
        return -3.5
    if word.startswith('electric'):
        if word.endswith('al'):
            return -2.8
        if word.endswith('ity'):
            return -3.35
        return -3.3 if token.strip().startswith('E') else -3.7
    if word.startswith(('électri', 'eléctr')):
        return -2.6
    if word in ('electro', 'electrom', 'electr'):
        return -3.3
    if word.startswith(('electron', 'electrode', 'electromag', 'electroly')):
        return -1.8
    if word in ('elect', 'élect'):
        return -3.2 if token.strip().startswith(('E', '-')) else -2.4
    if word.startswith(('elect', 'reelect')):
        return -1.05
    if word.startswith('elek'):
        return -1.8
    if word in ('voltage', 'oltage'):
        return -2.0
    if word in ('volt', 'volts'):
        return -1.25 if word == 'volt' else -0.85
    if word in ('ele', 'лект'):
        return -1.25
    if word == 'э':
        return -0.8
    if word.startswith((
        'telephone', 'téléphon', 'teléfon', 'телеф', 'telefon',
    )):
        return -1.9
    if word in ('tele', 'télé'):
        return -1.7
    if word.startswith(('telecom', 'telegraph', 'telegram')):
        return -1.1 if word != 'telegram' else -0.7
    if word.startswith(('email', 'e-mail', 'mailto')):
        return -1.4
    if token.lower() == '-mail':
        return -0.9
    if word == 'radio' or word.startswith((
        'phone', 'magnet', 'battery', 'batteries',
    )):
        return -0.85 if word in ('phones', 'batteries') else -1.2
    if word in ('computer', 'power', 'powered', 'powering'):
        return -0.7
    if word in ('computers', 'powers'):
        return -0.35
    if word.startswith('resistor'):
        return -0.9
    if word.startswith(('circuit', 'charg', 'television', 'bipolar')):
        return -0.5
    if word in ('agnet', 'attery', 'lectron', 'photoc', 'cellphone', 'kwh', 'eeg'):
        return -1.0
    if word in ('lect', 'lectric', 'agnetic', 'phot'):
        if word == 'lectric':
            return -1.75
        return -0.7 if word == 'lect' else -0.8
    if word in ('photo', 'photos'):
        return -0.3
    if word.startswith((
        'wireless', 'capacitor', 'transistor', 'laptop', 'proton', 'photon',
    )):
        return -0.4
    if word == '磁':
        return -1.9
    if word in ('雷', '雳', '光伏', 'ไฟ'):
        # Thunder/lightning, photovoltaic power, Thai fire/electricity.
        return -1.3
    return 0.0


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    previous = carry[1] if carry is not None and carry[0] == doc else ''
    word = token.strip().lower()
    value = lexical_value(token)
    if word == 'rical' and previous.lower().endswith('elect'):
        value = -2.3 if 'E' in previous else -1.5
    elif word == 'lect':
        if previous.lower().endswith('oe'):
            value = -1.15
        elif previous.lower().endswith('e'):
            value = -1.9
    elif word == 'lectric':
        if previous.lower().strip() == 'die':
            value = -1.3
        elif previous.lower().endswith('oe'):
            value = -2.5
    # Charging, conducting, or transmitting electricity weakens this response.
    elif word in ('电', '電') and previous.endswith(tuple('充导導输輸')):
        value = -6.0
    if '\ufffd' in token:
        # A split UTF-8 token can finish the electricity character.
        if prefix.text_prefixes[-1].endswith(('电', '電')):
            value = -5.5
    return (doc, token), value

"""A small auxiliary-verb detector.

'Been' is positive. 'Be' and 'have' respond especially strongly to future
and conditional auxiliaries. Frequency/time adverbs instead give a
negative response after strong modals. Other intervening words weaken
that response; 'going to' also signals a future. Unrecognized tokens
predict zero. These rules summarize the dominant auxiliary/modal pattern,
not the smaller token-specific effects. Five recent token cues are kept
and reset at document boundaries.
"""
READS = ()

# Responses to (be, have) immediately after a modal.
MODAL = {
    'will': (5.66, 2.86), 'shall': (4.44, 2.22),
    'would': (3.63, 2.00), 'should': (2.30, 1.07),
    'might': (1.33, 0.61), 'must': (0.95, 0.39),
    'may': (0.91, 0.31), 'could': (0.82, 0.45),
    'can': (-0.14, 0.09), 'cannot': (-0.05, 0.18),
    "'ll": (6.61, 3.56), "'d": (3.92, 2.50),
    'gonna': (4.30, 2.10),
}
NEGATED = {
    'won': (5.20, 2.99), 'wouldn': (3.60, 2.70),
    'shouldn': (2.19, 1.00), 'couldn': (0.80, 0.45),
    'can': (-0.12, 0.20), 'don': (0.50, 1.03),
    'doesn': (0.40, 0.84), 'didn': (0.45, 0.90),
}
MODAL.update({word + "'t": response for word, response in NEGATED.items()})

EXPECTATION = {
    'likely', 'supposed', 'expected', 'seem', 'seems', 'seemed',
    'appear', 'appears', 'appeared', 'tend', 'tends', 'ought',
}

ADVERBS = {'always', 'never', 'ever', 'often', 'usually', 'typically',
           'generally', 'eventually', 'soon', 'still'}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    recent = [] if carry is None or carry[0] != doc else carry[1]
    raw = prefix.token_strings[-1]
    word = raw.strip().lower().replace('’', "'")
    if not word and '\n' in raw:
        word = '\n'
    prev = recent[-1] if recent else ''
    value = 0.0
    if word == 'been':
        value = 1.75
    elif word in ADVERBS:
        value = -0.25 if word in {'eventually', 'soon', 'generally'} else 0.15
        if prev in MODAL:
            factor = 0.25 if word == 'still' else 0.50
            value -= factor * max(0.0, MODAL[prev][0] - 1.0)
    elif word in {'be', 'have'}:
        which = int(word == 'have')
        value = (0.05, 0.40)[which]
        if prev == 'to':
            before = recent[-2] if len(recent) > 1 else ''
            value = (0.05, 0.10)[which]
            if before == 'going':
                value = (3.92, 2.04)[which]
            elif before in EXPECTATION:
                value = (1.06, 0.40)[which]
        else:
            for distance, previous in enumerate(reversed(recent), 1):
                if any(c in previous for c in '.!?;\n'):
                    break
                if previous in MODAL:
                    value = MODAL[previous][which]
                    value *= (1.0, 0.78, 0.40, 0.22, 0.12)[distance-1]
                    if prev in {'never', 'always', 'ever'}:
                        value *= 0.70
                    break
    if word == "'t" and prev in NEGATED:
        # Combine split contractions into a single grammatical cue.
        word = prev + "'t"
        recent = recent[:-1] + [word]
    else:
        recent = (recent + [word])[-5:]
    return (doc, recent), float(value)

programs.haiku:
"""Draft 3: a bare 'be', 'been' or 'have' that carries a future, modal or perfect meaning.

The component reads the word just before the verb, skipping negation and adverbs
("will not be", "would also have"). It fires on the bare verb "be" after a future
auxiliary (will, 'll, shall, would, 'd, won't, going to), more weakly after should or
the weaker modals, and on "been" after has/have/had; "have" fires after will or would.
"""
READS = ()

# Activation of a bare "be" by the auxiliary before it.
BE_AFTER = {"will": 5.5, "'ll": 6.2, "’ll": 6.2, "won": 5.3, "shall": 4.3, "would": 3.6,
            "'d": 3.9, "’d": 3.9, "should": 2.2, "might": 1.3, "must": 0.9, "may": 0.9,
            "could": 0.8, "can": 0.0}
# "been" after perfect "have" / "has" / "had".
BEEN_AFTER = {"has": 1.8, "have": 1.7, "had": 1.9, "'ve": 2.3, "’ve": 2.3}
# "have" after a modal or do-support.
HAVE_AFTER = {"will": 2.7, "would": 1.9, "should": 1.1, "’t": 1.0, "'t": 1.0, "do": 0.8,
              "does": 0.6, "did": 0.9}
# Words skipped between the auxiliary and the verb: negation and adverbs.
SKIP = {"not", "n't", "’t", "never", "also", "still", "always", "only", "just", "ever", "yet"}
# Foreign-language future auxiliaries ("будет", "será", "będzie") act the same way.
FOREIGN_FUTURE = {"будет", "будут", "será", "serán", "będzie", "będą"}


def word(prefix, i):
    return prefix.token_strings[i].strip().lower()


def step(carry, prefix, upstream):
    t = prefix.position
    cur = word(prefix, t)
    if cur in FOREIGN_FUTURE:
        return None, 1.3
    if cur not in ("be", "been", "have"):
        return None, 0.0
    j = t - 1
    while j >= 0 and word(prefix, j) in SKIP and prefix.document_ids[j] == prefix.document_ids[t]:
        j -= 1
    if j < 0 or prefix.document_ids[j] != prefix.document_ids[t]:
        return None, 0.0
    aux = word(prefix, j)
    if cur == "be":
        if aux == "to":
            # "going to be" is a future too
            going = j > 0 and word(prefix, j - 1) == "going"
            return None, 4.0 if going else 0.3
        return None, BE_AFTER.get(aux, 0.0)
    if cur == "been":
        return None, BEEN_AFTER.get(aux, 0.0)
    return None, HAVE_AFTER.get(aux, 0.5 if aux in ("we", "you", "i", "they") else 0.0)

programs.luna:
"""A compact lexical predictor for the component's sparse positive responses.

It raises its estimate on be, been, or being after an auxiliary or modal,
including 'not be' and a few common adverb + 'been' patterns. Other be forms
get a smaller positive estimate.
"""
READS: tuple[str, ...] = ()

_BE = {"be", "been", "being"}
_AUXILIARIES = {
    "am", "is", "are", "was", "were", "have", "has", "had",
    "will", "would", "can", "could", "shall", "should", "may",
    "might", "must", "to",
}
_MODALS = {
    "will", "would", "can", "could", "shall", "should",
    "may", "might", "must",
}
_ADVERBS = {"recently", "always", "already", "never", "just", "ever"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word not in _BE:
        return None, 0.0

    if len(prefix.token_ids) < 2:
        return None, 0.15
    same_doc = prefix.document_ids[-2] == prefix.document_ids[-1]
    if not same_doc:
        return None, 0.15

    previous = prefix.token_strings[-2].strip().lower()
    if previous in _AUXILIARIES:
        return None, 1.5

    if previous == "not" and len(prefix.token_ids) > 2:
        same_three = (
            prefix.document_ids[-3]
            == prefix.document_ids[-2]
            == prefix.document_ids[-1]
        )
        before_not = prefix.token_strings[-3].strip().lower()
        if same_three and before_not in _MODALS:
            return None, 1.5

    if word == "been" and previous in _ADVERBS and len(prefix.token_ids) > 2:
        same_three = (
            prefix.document_ids[-3]
            == prefix.document_ids[-2]
            == prefix.document_ids[-1]
        )
        before_adverb = prefix.token_strings[-3].strip().lower()
        if same_three and before_adverb in {"have", "has", "had"}:
            return None, 1.5

    return None, 0.15

