READS = ()

EARLY = 0.007
NON_LATIN = 0.008
WORD_PIECE = -0.0026
WORD_START = -0.0007


def _is_latin_letter(ch):
    return ch.isalpha() and ord(ch) < 0x250


def step(carry, prefix, upstream):
    idx = 0 if carry is None else carry
    if len(prefix.document_ids) > 1 and prefix.document_ids[-1] != prefix.document_ids[-2]:
        idx = 0
    s = prefix.token_strings[-1]
    body = s.strip()
    value = 0.0
    if idx < 2:
        value = EARLY
    elif body and body[0].isalpha():
        if not _is_latin_letter(body[0]):
            value = NON_LATIN
        elif s[:1] == " ":
            value = WORD_START
        else:
            value = WORD_PIECE
    return idx + 1, float(value)

