"""A detector for greater-than and related comparison notation.

Right angle brackets give the largest signal. Their spacing, trailing newline,
and whether they close a lowercase markup name or a type-like name adjust it.
Comparison words, arrows, equality tests, vertical bars, and right-facing
quotation marks give weaker signals. 'Than' is strong after 'greater' and weak
in 'rather than'. Fraction notation, empty collections and HTTP prefixes are
small side responses. Other text is zero. The 160-character history resets
between documents. Coefficients are fitted from training activations.
"""
import re

READS = ()
TYPE_NAMES = set('int long short byte char float double bool string str '
                 'object any u8 i32 u32'.split())
ANGLE_NAME = re.compile(r'<(/?)([A-Za-z_][\w:]*)$')
COMPARISONS = {
    'greater': 1.45, 'beyond': 0.98, 'more': -0.07,
    'exceed': 1.05, 'exceeds': 1.27, 'exceeded': 0.98, 'exceeding': 1.07,
    'larger': 0.58, 'bigger': 0.56, 'longer': 0.35, 'greatest': 0.40,
    '超': 1.13, '越': 1.03, '超过': 0.86, '超越': 0.74, '大于': 1.98,
    'größer': 1.24, 'больше': 0.66, 'более': 0.36, 'hơn': 0.61,
}
SYMBOLS = {
    '＞': 2.21, '＜': 0.57, '≫': 1.22, '≥': 0.67, '≤': 0.23, '≠': 0.57,
    '→': 0.45, '⇒': 0.36, '》': 0.89, '」': 0.59, '』': 0.62, '】': 0.30,
    '»': 0.75, '›': 1.10, '«': 0.21, 'http': 0.63, 'https': 0.63,
}
THAN_AFTER = {
    'greater': 1.57, 'larger': 1.31, 'bigger': 1.31, 'longer': 1.07,
    'less': 0.48, 'lower': 0.48, 'fewer': 0.48, 'rather': 0.19,
    'better': 0.73, 'smaller': 0.73, 'shorter': 0.73,
}


def response(token, previous, history):
    s = token.strip()
    space, newline = token.startswith(' '), '\n' in token or '\r' in token
    if s.startswith('<') and s.endswith('>') and any(c.isalpha() for c in s):
        return 0.0  # Complete tags/chat markers are not isolated brackets.
    if s.lower() == 'than':
        return THAN_AFTER.get(previous.strip().lower(), 0.84)
    if s.lower() in COMPARISONS:
        return COMPARISONS[s.lower()]
    if s in SYMBOLS:
        return SYMBOLS[s] + (0.20 if s == '»' and space else 0.0)
    if s in {'gt', '&gt'}:
        return 2.20 if '&' in previous or s.startswith('&') else 0.65
    if s == ';' and previous.strip() in {'gt', '&gt'}:
        return 2.00
    if s == 'frac':
        return 0.85 if '\\' in previous else 0.40
    if '->' in s or '=>' in s:
        return (0.90 if space else 1.08) if '->' in s else (0.62 if space else 1.0)
    if s == '>':
        if space:
            return 1.47 if newline else 3.53
        angle = ANGLE_NAME.search(history)
        if angle:
            closing, name = angle.groups()
            markup = name[0].islower() and name not in TYPE_NAMES
            if newline:
                return (0.02 if closing else 0.26) if markup else 0.62
            if markup:
                return 1.22 if closing else 1.55
            return 2.11 if len(name) == 1 else 2.75
        whitespace = previous and previous[-1].isspace()
        if newline:
            return 1.30 if whitespace else 0.62
        return 3.38 if whitespace else 3.03
    if '>' in s:
        if s == '>&':
            return 1.40  # Shell redirection.
        if s.startswith('>') and s[1:].isalpha():
            return 1.35  # Bracket fused to the next word.
        if s.endswith('>') and s[:-1] in {'[]', ']', ')'}:
            return 3.00
        if '>=' in s:
            return 1.04
        if set(s) == {'>'}:
            return 0.40 if newline else 2.20
        return 0.50 if newline or s.startswith('>') else 1.65
    if '<' in s:
        if '<=' in s or '<<' in s or '<-' in s or s.startswith('</'):
            return 0.30
        before = previous.strip()
        if s == '<' and not newline:
            if space and previous and not before:
                return 0.25
            if before.isdigit() or len(before) == 1 and before.isalpha():
                return 1.20
        return 0.50 if newline else 0.75
    if '::' in s or '!=' in s or s in {'==', '==='}:
        return 0.70
    if '|' in s and '||' not in s:
        return 0.40 if newline else 0.60
    if '[]' in s or s == '{}':
        return 0.50
    return 0.0


def step(carry, prefix, upstream):
    doc, token = prefix.document_ids[-1], prefix.token_strings[-1]
    previous, history = ('', '') if carry is None or carry[0] != doc else carry[1:]
    value = response(token, previous, history)
    return (doc, token, (history + token)[-160:]), float(value)

