GREATER_TAIL = {">=", " >=", ">&", "&gt", "gt", " ?>"}
LESS_SIGN = {"<", " <", "<=", " <=", "&lt", "lt", "＜"}
EXCEED_WORDS = {"than", " than", "greater", " greater", "larger", " larger", "bigger", " bigger",
                "exceeds", " exceeds", "exceed", " exceed", "beyond", " beyond",
                "超", " 超", "超过", "超越", "高于", "越", "超過"}
ARROWS = {"->", " ->", "=>", " =>", "-->", " -->", "→", " →", "⇒", " ⇒", "<-", " <-"}
EQUALITY = {"==", " ==", "===", " ===", "!=", " !=", "!==", " !==", "≠", " ≠", "≥", " ≥", "≤", " ≤"}
PIPES = {"|", " |", "::", " ::"}


def step(carry, prefix, upstream):
