Han content, lone replacement-glyph byte pieces, title-case words, and tool
handoff tags get modestly higher estimates; ordinary tokens stay near zero.
"""

import unicodedata

READS = ()

TOOL_MARKERS = {
    "<tool_call>": 1.42,
    "</tool_call>": 0.70,
    "</tool_response>": 2.00,
}

# Common grammatical words, used only to separate them from Han content words.
HAN_FUNCTION_WORDS = frozenset(
    "的了是我你他她它们这那在有不就也都很把被对和而为与以从将会能要可"
    "之于及又还再所着过没什么怎么谁哪每各其且但若并虽因"
)
ENGLISH_FUNCTION_WORDS = frozenset(
    "the of and to a in is it for on with as at by from that this are an be or "
    "but not have has he she they we you i his her their our which who what "
    "when where how if then so do does did been into about after before also".split()
)


def is_han(char):
    code = ord(char)
    return (
        0x3400 <= code <= 0x4DBF
        or 0x4E00 <= code <= 0x9FFF
        or 0xF900 <= code <= 0xFAFF
        or 0x20000 <= code <= 0x323AF
    )


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    if token in TOOL_MARKERS:
        return None, float(TOOL_MARKERS[token])
    if token == "\ufffd":
        # A lone replacement glyph is how an incomplete UTF-8 byte piece decodes.
        return None, 0.195

    chars = [c for c in token if not c.isspace() and c != "\ufffd"]
    if not chars:
        return None, 0.009
    if all(is_han(c) for c in chars):
        if "".join(chars) in HAN_FUNCTION_WORDS:
            return None, -0.011
        return None, 0.051
    if all(c.isalpha() and "LATIN" in unicodedata.name(c, "") for c in chars):
