            return None, 0.001
        if token.strip().istitle():
            return None, 0.011
        return None, 0.005
    if all(c.isalpha() for c in chars):
        return None, 0.004
    if all(c.isdigit() for c in chars):
        return None, -0.002
    if all(unicodedata.category(c).startswith("P") for c in chars):
        return None, 0.002
    if any(c.isalpha() for c in chars):
        return None, 0.016
    return None, 0.0

