"""A sparse signal for Unix/open-source software, packaging and licensing.

Tool names, repository files, package metadata and license terms are positive.
Build/source words are stronger after software-like text. The placeholder
NAME is another positive cue. Completed names can span tokens. Two additional
phrase-completion signals are 'at least' and 'how to'. A short past-text tail
resets at each document; other text is zero.
"""
import re

READS = ()
UNIX_NAMES = {
    'GNU': 1.6,
    'Debian': 2.5,
    'Bison': 2.2,
    'BSD': 1.9,
    'GPL': 1.5,
    'POSIX': 1.3,
}
SYSTEMS = {'Linux', 'UNIX', 'GCC', 'clang', 'Emacs', 'Perl', 'Boost',
           'Apache', 'PostgreSQL'}
REPOSITORY_FILES = {'README', 'LICENSE', 'COPYING', 'INSTALL', 'CHANGELOG'}
LICENSE_TERMS = {'MERCHANTABILITY', 'WARRANTY', 'FITNESS', 'DAMAGE'}
BUILD_WORDS = {'build', 'Build', 'configure', 'crates'}
LIBRARY_WORDS = {'lib', 'pkg', 'dependencies', 'documentation', 'stdio'}
SOURCE_WORDS = {'source', 'sources', 'changes', 'directory', 'repository'}
SOFTWARE_MARKERS = ('```', '`', 'import ', 'def ', 'git ', 'cargo ',
                    'pip ', 'npm ', '.py', '/', '\\', 'file', 'package',
                    'code', 'software', 'compile', 'test', 'library')


def software_context(text):
    lowered = text.lower()
    return any(marker in lowered for marker in SOFTWARE_MARKERS)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    old = '' if carry is None or carry[0] != doc else carry[1]
    s = prefix.token_strings[-1]
    tail = (old + s)[-160:]
    word = s.lstrip(' \t/._-(')
    value = 0.0

    makefile = re.search(r'\b([Mm]akefile)$', tail)
    if makefile:
        value = 2.15 if makefile[1] == 'Makefile' else 1.4
    elif re.search(r'\b[Ss]etuptools$', tail):
        value = 2.3 if s == 'uptools' else 1.55
    elif re.search(r'\btravis$', tail):
        value = 0.46
    elif re.search(r'\b[Ll]isp$', tail):
        value = 1.4
    elif re.search(r'\bgolang$', tail):
        value = 0.77
    elif word in UNIX_NAMES:
        value = UNIX_NAMES[word]
    elif word in SYSTEMS: value = 1.0
    elif word in {'libc', 'gettext', 'unistd', 'setq'}: value = 1.5
    elif word in REPOSITORY_FILES: value = 0.72
    elif word in LICENSE_TERMS: value = 0.65
    elif word == 'Public' and old.endswith('General'): value = 0.83
    elif word == 'org':
        value = 0.45 if s == 'org' else 0.9
        if s == '.org':
            value = 0.7
            if re.search(r'(apache|gnu|mozilla|rust-lang)$', old):
                value = 1.95
            elif re.search(r'(golang|python|gradle|opensource)$', old):
                value = 1.3
    elif word == 'gnu':
        value = 1.8 if s.startswith('.') else 1.0
    elif word == 'apache': value = 1.3
    elif word == 'git':
        value = 1.2 if old.endswith(' --') else 0.6
    elif word in BUILD_WORDS:
        value = 0.65 if software_context(old) else 0.3
    elif word in {'Make', 'make'}:
        value = 0.25 if word == 'Make' else 0.08
        if software_context(old): value = 0.7
    elif word == 'dist':
        value = 0.5 if software_context(old) else 0.14
    elif word in LIBRARY_WORDS: value = 0.45
    elif word in SOURCE_WORDS:
        value = 0.35 if software_context(old) else 0.15
        if s == '/sources' and old.endswith('/apt'): value = 1.38
    elif word == 'apt':
        value = 0.5 if software_context(old) else 0.0
        if s.startswith('/'): value = 1.1
    elif s == '.list' and '/apt/' in old:
        value = 1.58 if old.endswith('/sources') else 0.75
    elif s == '_requires': value = 0.71
    elif s in {'.cfg', '.mk', '.spec'}: value = 0.5
    elif word == 'usr':
        value = 0.42 if s.startswith('/') else 0.8
    elif word == 'etc' and s == 'etc' and old.endswith('/'):
        value = 1.03
    elif word == 'kernel' and 'Linux' in old: value = 1.3
    elif word == 'NAME':
        value = 0.47 if s.startswith(' ') else 0.1
    elif word == 'least':
        value = 0.69 if re.search(r'\b[Aa]t$', old) else 0.17
    elif word.lower() == 'to' and re.search(r'\b[Hh]ow$', old):
        value = 0.65
    return (doc, tail), float(value)

programs.haiku:
"""Layer-0 MLP component 1498 (down_proj), as a word-level program.

What it does: the component is active on the vocabulary of Unix / Linux / open-source
software projects, and it is strongest on:
  - operating-system and license names: Debian, Fedora, Linux, Unix, GNU, GPL, Apache;
  - web and path pieces of project URLs and file paths: .org, /org, .git, /repos, /lib,
    /pkg, /usr, /etc, .list;
  - project and build words: git, HEAD, LICENSE, README, Makefile, build, lib, dist, pkg,
    apt, usr, spec, repository;
  - tool, library and system names: Cargo, SQLite, malloc, iptables, Bison, kernel;
  - and on the second word of two fixed phrases: "how [to]", "at [least]".
Programming-language and everyday words (Python, Java, the, of, to) do not drive it.
Its output, read through the embedding, favours Linux, BSD and GPL-style continuations,
which fits this reading.

The program gives a fixed strength to each group and 0 otherwise. It reads only the current
token and the one before it (ignored across a document break).
"""

READS = ()

OS_AND_LICENSE = {"Debian", "Fedora", "Linux", "Unix", "unix", "_unix", "BSD", "GNU", "GPL",
                  "Apache", "apache", "gnu", "CDDL"}
URL_AND_PATH = {".org", "org", "/org", "-org", ".git", "/repos", "/lib", "/pkg", "/usr",
                "usr", "/etc", "etc", "/apt", "apt", ".list", "/sources", "/python", ".apache"}
PROJECT_WORDS = {"git", "HEAD", "LICENSE", "README", "Make", "build", "_build", "lib", "libs",
                 "dist", "pkg", "spec", ".spec", "repository", "repos", "FAIL", "FAILED",
                 "NAME", "file", "Source", "source", "requires", "_requires", "dependencies"}
SOFTWARE_NAMES = {"Kubernetes", "SQLite", "Redis", "Docker", "Ubuntu", "Firefox", "Cargo",
                  "crate", "malloc", "mesa", "conda", "perror", "stderr", "iptables", "helm",
                  "protobuf", "Bison", "configure", "kernel", "cmake", "autoconf", "yum", "deb"}
PHRASES = {("how", "to"): 0.6, ("How", "to"): 0.6, ("at", "least"): 0.6}
STRENGTH = {"os": 0.8, "url": 0.6, "project": 0.45}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    prev = prefix.token_strings[-2].strip() if len(prefix) > 1 else ""
    if len(prefix) > 1 and prefix.document_ids[-2] != prefix.document_ids[-1]:
        prev = ""
    if (prev, word) in PHRASES:
        return carry, PHRASES[(prev, word)]
    if prev == "Make" and word == "file":
        return carry, 2.0
    if word in OS_AND_LICENSE:
        return carry, STRENGTH["os"]
    if word in URL_AND_PATH:
        return carry, STRENGTH["url"]
    if word in PROJECT_WORDS:
        return carry, STRENGTH["project"]
    if word in SOFTWARE_NAMES:
        return carry, 0.35
    return carry, 0.0

