Sampled activations repeatedly rose on build and repository vocabulary, repository
file inventories, apt source-list paths, ``how to`` and ``least``, and uppercase
``NAME`` placeholders. The program marks those patterns, not the model's hidden
computation.
"""

READS: tuple[str, ...] = ()

BUILD_WORDS = frozenset({
    "build", "building", "built", "cargo",
})

REPOSITORY_WORDS = frozenset({
    "git", "gitignore", "license", "readme", "eof",
})

TECHNICAL_WORDS = frozenset({
    "repository", "dependencies", "directory", "source", "lib",
    "malloc", "pkg",
})

REPOSITORY_MARKERS = (
    ".gitignore", ".travis.yml", "readme", "license", "go.mod",
    "cargo.toml", "makefile",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    doc = prefix.document_ids[-1]

    if carry is None or carry[0] != doc:
        tail = ""
    else:
        tail = carry[1]

    recent = (tail + token).lower()[-320:]
    value = 0.0

    if word == "least":
        value = 0.62
    elif word == "to" and recent.endswith("how to"):
        value = 0.62
    elif word in BUILD_WORDS:
        value = 0.50
    elif word == "apt":
        value = 0.44
    elif word.strip("/") == "org":
        value = 0.85
    elif word.strip("/") in REPOSITORY_WORDS:
        value = 0.50
    elif word.strip("/") in TECHNICAL_WORDS:
        value = 0.28
    elif word == "bison":
        value = 0.80

