        elif word in {"license", "readme", "git", "go.mod", "makefile"}:
            value = max(value, 0.55)

    # Package-manager source-list paths in the sample contain /etc/apt/sources.list.
    apt_list = "apt/sources" in recent and "sources.list" in recent
    if apt_list and word.strip("/.") in {"apt", "etc", "sources", "list"}:
        value = max(value, 0.95)
    elif "apt.fury.io" in recent and word.strip("/") == "apt":
        value = max(value, 0.80)

    return (doc, recent), float(value)

