"""Discussion versus frames and supporting structures.

Positive scores mark discussion words; negative scores mark frameworks,
scaffolds, and structural supports, including Chinese and Russian forms.
Inflection, capitalization and document starts change discussion strength.
A one-token memory also recognizes
split discussion words and the prepositions in 'talk about', 'discussion
of', and 'framework of'. Memory resets at each new document. Unmatched
text gets zero: this explains the strong lexical signals, not the small
background fluctuations.
"""

READS = ()
DISCUSSION = {
    'discuss': 1.03, 'discussing': 1.06, 'discussion': 1.08,
    'discussed': 0.78, 'discusses': 0.84, 'discussions': 0.85,
}
TALK = {'talk', 'talks', 'talked', 'talking'}
SPEAK = {'speak', 'speaks', 'speaking', 'spoke', 'spoken'}
SUPPORTS = {
    'framework': -1.1, 'frameworks': -0.82,
    'frame': -0.55, 'frames': -0.4, 'iframe': -0.53, 'jframe': -0.6,
    'framed': -0.21, 'framing': -0.15, 'timeframe': -0.18,
    'scaff': -0.7, 'scaffold': -0.85, 'caffold': -0.85,
    'architecture': -0.42, 'architectures': -0.22,
    'skeleton': -0.3, 'skeletons': -0.3, 'skeletal': -0.24,
    'cage': -0.32, 'rack': -0.29, 'cabinet': -0.22, 'chassis': -0.53,
    '架': -4.7, '一架': -2.6, '支架': -2.6, '架子': -2.8,
    '框架': -1.3, '架构': -1.5, '骨架': -1.6,
    '框': -0.52, '撑': -0.6, '搭': -0.46, '搭建': -0.57,
    '棚': -0.45, 'рамках': -0.43, 'rahmen': -0.58,
}


def step(carry, prefix, upstream):
    doc = int(prefix.document_ids[-1])
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    token = prefix.token_strings[-1]
    text = token.strip().lstrip('/_-(.')
    word = text.lower()
    value = SUPPORTS.get(word, 0.0)
    if word in DISCUSSION:
        value = DISCUSSION[word]
        if text.startswith('D'):
            value += 0.25
        if first:
            value *= 2.2
    elif word == 'structure' and token[:1].isspace():
        value = -0.16
    elif word in {'disc', 'discourse', 'discourses'}:
        value = 0.25
    elif word in {'uss', 'ussed', 'ussion', 'ussions', 'ourses'}:
        if previous.endswith(('disc', 'isc', 'disk')):
            value = 0.8 if word == 'ussed' else 1.0
    elif word in {'topic', 'topics'}:
        value = 0.18
    elif word in {'conversation', 'conversations', 'community',
                  'communities', 'debate', 'dialogue', 'chat'}:
        value = 0.1
    elif word in {'讨论', '討論'}:
        value = 1.02

    if word in {'about', 'of', 'on', 'with'}:
        if previous in DISCUSSION:
            value = {'about': 0.68, 'of': 0.52, 'on': 0.35, 'with': 0.3}[word]
        elif previous in TALK | SPEAK:
            value = {'about': 0.51, 'of': 0.2, 'on': 0.08, 'with': 0.14}[word]
        elif word == 'of' and previous in {'framework', 'frameworks'}:
            value = -0.47
        elif word == 'of' and previous in {'frame', 'frames', 'structure'}:
            value = -0.18
    return (doc, word), value

