"""Layer-0 MLP down_proj component 1499.

Reads the current token only. It is positive on words for discussing
("discuss", "discussion", "discussed", "talk about", 讨论) and negative on
words for a supporting frame or framework ("framework", "frame", "scaffold",
架/框架/支架, "architecture"). Everything else is about zero.
"""
READS = ()

DISCUSS_WORDS = {"discuss", "discussion", "discussions", "discussed", "discussing", "discusses", "讨论", "討論"}
FRAME_WORDS = {"framework", "frameworks", "frame", "frames", "scaffold", "scaffolds", "scaffolding", "chassis", "架", "框架", "支架", "架构"}
ARCH_WORDS = {"architecture", "architectures"}
TALK_WORDS = ("talk", "talks", "talked", "talking")


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    previous = prefix.token_strings[-2].strip().lower() if len(prefix.token_strings) > 1 else ""
    if word.startswith("discuss") or word in DISCUSS_WORDS:
        value = 1.2
    elif word == "about" and previous in TALK_WORDS:
        value = 0.6
    elif word == "架":
