"""A small lexical sketch of a rare layer-0 feature.

The harvested high-impact tokens cluster around talking about a subject and
around physical frames or supports.  This predicts that coarse distinction;
it is not a general semantic parser.
"""

READS = ()

TALKING = ("discuss", "讨论")
STRUCTURES = (
    "frame", "framework", "scaff", "rack", "cage", "架", "рамк",
)


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()

    if any(word in token for word in TALKING):
        return None, 0.85

    if token == "about":
        context = prefix.text_prefixes[-1].lower()
        if any(word in context[-40:] for word in ("talk", "speak", "post")):
            return None, 0.5

    if any(word in token for word in STRUCTURES):
        if "framework" in token:
            return None, -0.75
        if "scaffold" in token:
            return None, -0.7
        if "рамк" in token:
            return None, -0.5
        if "架" in token:
            return None, -1.0
        return None, -0.5

    return None, 0.0

"""Predict positive activations on words for ordinary or standard choices.

The clearest cues are 'standard' and 'default'; related cues include
'original', 'basic', and 'usual'. The rules use readable token text, with a
small carry to recognize the C++ standard-library spelling 'std::'.
"""
READS = ()

STANDARD_WORDS = {
    "ordinary", "regular", "usual", "typical", "common", "basic",
    "canonical", "benchmark", "benchmarks", "familiar", "mundane",
    "straight", "original", "originally", "foundation", "platform",
    "ordinance", "trope", "customary", "conventional", "baseline",
    "reference",
}
DEFAULT_WORDS = {"default", "defaults"}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    previous, previous_doc = carry or ("", None)
    doc = prefix.document_ids[-1]

    if token in DEFAULT_WORDS or "default" in token:
        value = 1.8
    elif "standard" in token:
        value = 5.5
    elif token == "std":
        value = 1.1
    elif token in STANDARD_WORDS:
        value = 0.85
    elif "original" in token or "canonical" in token:
        value = 0.85
    elif "familiar" in token:
        value = 0.55
    elif token in {"normal", "normalized", "норм", "常", "التق"}:
        value = 0.75
    elif token in {"ormal", "onical"}:
        value = 0.55
    elif token == "::" and previous == "std" and previous_doc == doc:
        value = 0.95
    elif "⬜" in token:
        value = 0.45
    else:
        value = 0.0

    return (token, doc), float(value)

programs.sol:
"""Approximate forward-pointing phrases and explicitly identified small groups.

Complete 'the following', 'as follows', 'here is / here's', and definite or
pointed-at quantities ('the two', 'these three'). Ordinary number words and
indefinite quantifiers have much smaller, often negative responses. References
'above' and 'below' differ, including from their definite forms. Equivalent
list-introducing words in several languages and one kana spelling pattern are
also recognized. Coefficients approximate response sizes, not exact rules
of grammar. Smaller token-specific responses are mostly left unexplained.
Thinking delimiters receive fixed negative offsets.
"""
import re

READS = ()
# (Ordinary use, after 'the') for familiar counted quantities.
COUNTS = {
    'one': (-0.01, 0.28),
    'two': (0.05, 0.78),
    'three': (-0.04, 0.46),
    'four': (-0.07, 0.37),
    'five': (-0.08, 0.28),
    'six': (-0.08, 0.19),
    'seven': (-0.08, 0.18),
    'eight': (-0.10, 0.11),
    'nine': (-0.08, 0.15),
    'ten': (-0.01, 0.10),
    'eleven': (-0.06, 0.10),
    'twelve': (-0.10, 0.16),
}
REFERENCES = {
    'following': (0.07, 0.96),
    'follow': (0.06, 0.39),
    'above': (-0.16, 0.21),
    'below': (0.04, 0.69),
    'given': (-0.01, 0.15),
    'different': (-0.03, 0.24),
    'various': (-0.07, 0.21),
    'respective': (0.01, 0.20),
    'whole': (0.00, 0.14),
    'entire': (0.00, 0.11),
    'other': (0.02, 0.06),
    'same': (-0.07, 0.03),
    'only': (0.07, -0.08),
}
POSSESSIVES = {'my', 'your', 'his', 'her', 'our', 'their', 'its'}
# Whole tokens that mean 'following / as below' or refer back above.
LIST_TRANSLATIONS = {
    '以下': 0.35, '如下': 0.44, '下列': 0.52,
    '以上': -0.15, '上述': -0.10, '下記': 0.45,
    'siguiente': 0.61, 'siguientes': 0.68,  # Spanish
    'seguint': 0.62,  # Portuguese seguinte(s), split before its ending
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    word = token.strip().lower()
    match = re.search(r'(\w+)$', tail)
    prev = match.group().lower() if match else ''
    value = 0.002
    if word in COUNTS:
        ordinary, definite = COUNTS[word]
        value = definite if prev == 'the' else ordinary
        if prev in {'these', 'this'}:
            value = 0.87 * definite
            if word == 'one':
                value = 0.39 if prev == 'this' else ordinary
        elif prev in {'those', 'that'}:
            value = 0.48 * definite
        elif prev in POSSESSIVES or prev in {'a', 'an'}:
            value = 0.36 * definite
        elif prev in {'first', 'last', 'second'}:
            value = 0.22 * definite
        if token.strip() != word:
            value *= 0.65  # Titles/capitalized counts respond less strongly.
    elif word in REFERENCES:
        value = REFERENCES[word][prev == 'the']
        if prev == 'a' and word == 'follow':
            value = 0.24
        if prev == 'as' and word in {'above', 'below'}:
            value = -0.04 if word == 'above' else 0.35
    elif word == 'follows':
        value = 0.90 if prev == 'as' else 0.13
    elif word in {'every', 'either', 'neither'}:
        value = -0.10
    elif word in {'several', 'multiple'}:
        value = 0.10 if prev == 'the' else -0.06
    elif word in {'each', 'both', 'many'}:
        value = -0.03
    elif word in {'few', 'little'}:
        value = 0.12 if prev in {'a', 'the'} else 0.0
    elif word == 'any':
        value = 0.03
    if prev == 'here' and word in {"'s", '’s', 'is', 'are'}:
        value = 0.47 if word in {"'s", '’s'} else 0.25
    if token == 'ующ' and prev == 'след':
        value = 0.86  # Russian следующий / следующие, 'following'.
    elif word in {'gende', 'genden', 'gender'} and prev in {'fol', 'vol'}:
        value = 0.68  # German folgende(n), 'following'.
    elif word == 'ici' and prev == 'vo':
        value = 0.55  # French voici, 'here is'.
    elif word == 'đây' and prev in {'sau', 'dưới'}:
        value = 0.55  # Vietnamese 'following / below'.
    elif word in LIST_TRANSLATIONS:
        value = LIST_TRANSLATIONS[word]
    if prev == 'suiv' and word in {'ant', 'ante', 'ants', 'antes'}:
        value = 0.52  # French suivant(e)(s), 'following'.
    if prev == 'seguint' and word in {'e', 'es'}:
        value = 0.53  # Ending of Portuguese seguinte(s).
    # These references can be complete tokens or split between two tokens.
    for phrase in ('以下', '如下', '下列', '下記', '以上', '上述'):
        if (tail + token).endswith(phrase):
            value = LIST_TRANSLATIONS[phrase]
    if tail.endswith('ー�') and token.startswith('�'):
        value = 0.29  # Completing a kana after the Japanese long-vowel mark.
    if token == '<think>':
        value = -0.17
    elif token == '</think>':
        value = -0.06
    return (doc, (tail + token)[-40:]), float(value)

