"""'Following'-type words and small enumerating numbers that open a noun phrase after 'the'
or 'these' (e.g. 'the following', 'the two', 'these two', 'as follows', 'Here's')."""
READS = ()

# words that open a noun phrase: "the ...", "these ...", "as ..."
OPENERS = {" the", "The", " The", " these", " those", " This", " its", " this"}
# how strongly each word fires right after an opener
AFTER_OPENER = {" following": 1.0, " two": 0.8, " three": 0.45, " four": 0.37,
                " one": 0.27, " five": 0.27, " above": 0.2}
# 'two' also fires after some other determiner-like words, but not after 'of' or 'and'
WEAK_TWO_PREV = {" are", " were", " his", " its", " any", " no", " other", " first", " only"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    same = len(prefix) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = prefix.token_strings[-2] if same else ""
    if prev in OPENERS and tok in AFTER_OPENER:
        return carry, AFTER_OPENER[tok]
    if tok == " two" and prev in WEAK_TWO_PREV:
        return carry, 0.25
    if tok == " follows" and prev == " as":
        return carry, 0.9
    if tok == "'s" and prev.strip() == "Here":
