programs.luna:
"""Predict a rare contribution from two short phrase patterns in harvested text.

It is strongest on “the following” and weaker on “the” plus a small number or
“below”. A separate weaker cue is the start of “Here’s …”.
"""

READS = ()

SEQUENCE_WORDS = {"following", "below"}
NUMBER_VALUES = {"two": 0.76, "three": 0.48, "four": 0.35, "deux": 0.35}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().casefold()
    if len(prefix.token_strings) > 1:
        same_document = prefix.document_ids[-2] == prefix.document_ids[-1]
        previous = prefix.token_strings[-2].strip().strip("\"'([{“‘").casefold()
        if same_document:
            if word == "following" and previous == "the":
