programs.sol:
"""A sparse Q/q response, strongest for standalone Q at document/line starts.

Q continuing uppercase text is weaker; q completing a TeX comparison is
positive. Smaller negative rules cover doubled Q, short Q acronyms,
q-ending forms, queue spellings and Q-prefixed capitalized names. C
#include is a separate weaker trigger. Unmatched tokens predict zero.
A short text tail and a position counter reset at every document boundary.
"""
import math
import re

READS = ()
COMPARISON = re.compile(r'\\(?:le|ge|ne|sime|prece|succe)$')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, position = ('', 0) if carry is None or carry[0] != doc else carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip()
    letters = ''.join(c for c in word if c.isalpha())
    line_start = tail.rstrip(' \t').endswith('\n')
    value = 0.0
    if letters == 'Q':
        early = 1.0 / math.sqrt(position + 4)
        spaced = token != word
        if word != 'Q':
            value = -1.7
        elif position == 0:
            value = -3.97 if spaced else -5.72
        elif line_start:
            value = (-2.15 if spaced else -2.55) - 2.9 * early
        elif tail and tail[-1].isascii() and tail[-1].isupper():
            value = -1.3 - early
        else:
            value = (-1.87 if spaced else -2.05) - 2.3 * early
    elif letters == 'q':
        if token == 'q' and COMPARISON.search(tail):
            value = 0.55
        elif token == 'q' and position == 0:
            value = -2.04
        elif word == 'q' and token != word:
            value = -0.49
        elif line_start:
            value = -0.9
        else:
            value = -0.6 if token == 'q' else -0.75
    elif letters == 'QQ':
        value = -2.15 if token != word else -1.7
    elif 'queue' in word.lower():
        value = -0.6
    elif letters.isascii() and letters.isupper() and 'Q' in letters:
        if len(letters) == 2:
            value = -0.75 if letters.endswith('Q') else -0.33
        elif len(letters) == 3 and letters.endswith('Q'):
            value = -0.35
    elif word.startswith('Q') and len(word) > 1 and word[1].isupper():
        value = -1.3  # Q-prefixed capitalized names, e.g. QWidget.
    elif letters.isascii() and letters.endswith('q'):
        if letters.lower() in {'eq', 'sq'}:
            value = -0.25  # Equality/square abbreviations.
        else:
            value = -0.65 if len(letters) == 2 else -0.15
    elif word == '#include':
        value = -0.6 if position == 0 else -0.15
    return (doc, (tail + token)[-64:], position + 1), value

