programs.sol:
"""A signed local response to continuations of numbers.

Consecutive decimal digits, including fullwidth digits, use a shared response
shape: a bump at 1 and a ramp above 4. Its sign and scale depend on the preceding
digit. Responses are especially negative after 3--5 and before 8 or 9, and
weaker across a separator. Dimensional, ordinal, and one- or two-letter ASCII
suffixes instead receive positive values. Written English numbers are handled
before '-dimensional'. Other cases receive zero. State is just the last two
tokens, cleared at document boundaries.
"""
import math
import unicodedata

READS: tuple[str, ...] = ()

# Previous decimal digit -> (offset, inhibition strength).
# The common response dips at 1 and falls again above 4.
DIGIT_RESPONSE = (
    (-.111, -.187), (-.025, -.049), (.495, .886),
    (.007, 1.957), (-.436, 1.166), (.053, 1.057),
    (.128, .269), (.424, .449), (.008, -.004), (.048, .041),
)
NUMBER_WORDS = dict(zip(
    ('zero', 'one', 'two', 'three', 'four', 'five',
     'six', 'seven', 'eight', 'nine'), range(10)))
SEPARATOR_STRENGTH = {'.': .25, '-': .15, ',': .10,
                      ':': .08, ' ': .30, 'e': .15}
DIMENSION = (.2, .25, 1.8, 3.0, 1.65, 1.5, .9, .8, .4, .2)
ORDINAL = (.63, .70, 1.21, 1.46, .89, .91, .86, .90, .76, .75)


def digit(s):
    if len(s) != 1:
        return None
    try:
        return unicodedata.decimal(s)
    except ValueError:
        return None


def digit_effect(previous, current):
    offset, strength = DIGIT_RESPONSE[previous]
    shape = .4 * max(current - 4, 0) + math.exp(-.5 * (current - 1)**2)
    return offset - strength * shape


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    token = prefix.token_strings[-1]
    if carry is None or carry[0] != doc:
        previous, before_previous = '', ''
    else:
        _, previous, before_previous = carry
    p, d = digit(previous), digit(token)
    value = 0.0
    if d is not None:
        if p is not None:
            value += digit_effect(p, d)
        elif previous in SEPARATOR_STRENGTH:
            q = digit(before_previous)
            if q is not None:
                value += SEPARATOR_STRENGTH[previous] * digit_effect(q, d)
    elif p is not None:
        if token in ('D', 'd', '-d', '-D', '-dimensional'):
            scale = .78 if token == 'd' else .52 if token in ('-d', '-D') else 1.0
            value = DIMENSION[p] * scale
        elif token == 'th':
            value = ORDINAL[p]
        elif token in ('st', 'nd', 'rd'):
            value = {'st': .57, 'nd': .49, 'rd': 2.0}[token]
            if p != {'st': 1, 'nd': 2, 'rd': 3}[token]:
                value = .25
        elif token == 's':
            value = .55
        elif 1 <= len(token) <= 2 and token.isascii() and token.isalpha():
            value = .65 if p in (2, 3) else .48 if p in (5, 6, 7) else .33
    elif token == '-dimensional':
        n = NUMBER_WORDS.get(previous.strip().lower())
        if n is not None:
            value = DIMENSION[n] * .8
    return (doc, token, previous), float(value)

"""Approximate the component's largest lexical responses.

The strong words are 'speaker', 'great', and spatial/structural labels.
Nearby wording distinguishes a front part from 'in front', and ordinary
'main' from a code entry point. Equipment lexemes get a moderate response.
Other lexical variation is deliberately left at zero.
"""
READS = ()
ARTICLES = {'the', 'a', 'an'}
CODE_DECLARATIONS = {'int', 'void', 'func', 'def', 'fn', 'package'}
LOCATIONS = {
    'front': 0.85, 'rear': 0.85, 'side': 0.60, 'sides': 0.37,
    'main': 0.30, 'internal': 0.45, 'external': 0.66,
    'exterior': 0.45, 'upper': 0.33, 'inner': 0.19, 'outer': 0.19,
}
