    'door', 'doors', 'hood', 'windshield', 'exhaust', 'shower',
    'brake', 'brakes', 'braking', 'ignition', 'steering', 'seat',
    'belt', 'transmission', 'roof', 'kitchen', 'cooker', 'cabinet',
    'fan', 'intake', 'combustion', 'locking', 'auxiliary', 'removable',
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    previous = '' if carry is None or carry[0] != doc else carry[1]
    token = prefix.token_strings[-1]
    bare = token.strip()
    word = bare.lower()
    label = word.lstrip('/_-')  # location words also appear in identifiers
    spaced_lower = token.startswith(' ') and bare.islower()
    value = LOCATIONS.get(label, 0.0)

    if label in {'front', 'rear', 'main', 'upper'} and not spaced_lower:
        value *= 0.60
