        value = 1.35 if bare == 'speaker' and previous == 'the' else 0.75
    elif word == 'great':
        value = 0.67 if bare.islower() else 0.73
    elif label in {'front', 'rear'}:
        if previous in ARTICLES and spaced_lower:
            value = 1.15
        elif previous == 'in':
            value = 0.65
    elif label == 'main':
        if previous in ARTICLES:
            value = 0.65
        elif previous in CODE_DECLARATIONS:
            value = 0.02
    elif label == 'side':
        if previous in {'left', 'right', 'opposite', '-hand'}:
            value = 0.75
        elif previous in {'each', 'that'}:
            value = 0.38
    elif label in {'internal', 'upper'} and previous in ARTICLES:
        value = 0.55 if label == 'internal' else 0.47
    elif label == 'external' and not spaced_lower:
