    "subject", "sure", "unwilling", "young",
})

QUALITY_ENDINGS = (
    "able", "ible", "ful", "less", "ous", "ive", "ic", "al",
    "ent", "ant", "ed",
)

FORMS_OF_BE = frozenset({
    "am", "is", "are", "was", "were", "be", "been", "being",
    "i'm", "you're", "we're", "they're", "it's", "that's",
