programs.sol:
"""Approximate a semicolon and syntax-boundary response.

Prose semicolons are positive; HTML character-reference endings are much
stronger. Semicolons fused with code punctuation or line breaks are weaker.
There are secondary responses to LaTeX argument braces, HTML tag endings,
backticks, and tool-call markers. Ordinary text is assigned zero. Only a
short text suffix is carried, reset at each document boundary.
"""
import re
from html.entities import html5

READS = ()
ENTITY = re.compile(r'(?:&|&amp;)(#\d+|#x[\da-fA-F]+|[A-Za-z]\w*)$')
BARE_ENTITY = re.compile(r'(?<![A-Za-z])(amp|nbsp|lt|gt|quot|apos)$')
COMMAND = re.compile(r'\\([A-Za-z]+)$')
TAG = re.compile(r'<(/?)([a-z][a-z0-9]*)[^<>]*$')

# Familiar LaTeX command families: fonts, fractions, accents, references.
ARGUMENTS = (
    (0.85, {'text', 'mathrm', 'mathbf', 'mathbb', 'textbf', 'emph',
            'operatorname'}),
    (0.70, {'frac', 'dfrac', 'tfrac', 'mathcal'}),
    (0.60, {'vec', 'mathfrak', 'textup', 'widetilde'}),
    (0.45, {'sqrt', 'hat', 'widehat', 'overline', 'underline', 'bar',
            'tilde', 'overrightarrow', 'mbox', 'ce', 'hspace', 'textrm'}),
    (0.22, {'ref', 'label', 'eqref'}),
    (0.02, {'begin'}),
    (0.14, {'end'}),
)
INLINE_TAGS = {'code', 'span', 'strong', 'em', 'sub', 'sup', 'i', 'tt'}
TABLE_LIST_TAGS = {'td', 'th', 'li', 'a', 'b'}
BLOCK_TAGS = {'p', 'div', 'tr', 'ul', 'ol', 'pre', 'br', 'h1', 'h2', 'h3'}


def semicolon(s, tail, previous):
    left, right = s.split(';', 1)
    match = ENTITY.search(tail + left)
    name = match[1] if match else ''
    if name.startswith('#') or name + ';' in html5:
        value = {'lt': 4.1, 'amp': 3.35, 'gt': 2.88,
                 'quot': 2.6, 'apos': 2.55}.get(name, 1.5)
        if name.startswith('#'):
            try:
                number = int(name[2:], 16) if name[1:2] == 'x' else int(name[1:])
                value = 2.55 if number < 128 else 1.5
            except ValueError:
                pass
        if '\n' in right:
            return value * 0.2
        if right.startswith('</'):
            return value * 0.75
        if right.startswith('/'):
            return value * 0.65
        return value if not right else value * 0.5 + 0.15
    if BARE_ENTITY.search(tail + left):
        return 1.5 if not right else 0.8
    if '\n' in right:
        return -0.06 - 0.1 * (right.count('\n') > 1)
    if not left.strip() and not right:
        value = 0.7 - 0.07 * (not previous.startswith(' '))
        if previous.isascii() and previous.isdigit() and previous != '0':
            value += 0.12
        if sum(ch in '=[]{_<>/' for ch in tail[-100:]) >= 3:
            value -= 0.22
        if '=' in tail.rsplit('\n', 1)[-1][-20:]:
            value -= 0.1
        return value
    if right.startswith('//'):
        return 0.06
    if left.strip():
        if left.endswith(('}', ']')):
            return 0.45
        if left.endswith('.'):
            return 0.52
        return 0.06 if '()' in left else 0.28
    return 0.45 if right.startswith('\\') else 0.6


def tag_ending(s, tail):
    left, right = s.split('>', 1)
    match = TAG.search(tail + left)
    if not match:
        return 0.0
    closing, tag = match.groups()
    if tag in INLINE_TAGS:
        value = 1.0 if closing else 0.85
    elif tag in TABLE_LIST_TAGS:
        value = 0.4
    else:
        value = 0.12 if tag in BLOCK_TAGS else 0.0
    if left.endswith(('"', "'")) and tag != 'span':
        value *= 0.75
    if '\n' in right:
        return value * 0.2
    if '<' in right:
        return value * 0.45
    return value * 0.75 if right.startswith(',') else value


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    tail, previous = ('', '') if carry is None or carry[0] != doc else carry[1:]
    s = prefix.token_strings[-1]
    value = 0.0
    if s in {'<tool_call>', '</tool_call>'}:
        value = 0.92 if s == '<tool_call>' else 0.11
    elif ';' in s:
        value = semicolon(s, tail, previous)
    elif s == '；':
        value = 0.28
    elif s == '{':
        match = COMMAND.search(tail)
        value = 0.06 if not match else 0.3
        if match:
            for strength, commands in ARGUMENTS:
                if match[1] in commands:
                    value = strength
                    break
    elif s in {' `', '`'}:
        value = 0.09 if s.startswith(' ') else -0.01
        if tail.endswith(('`', '\u00a0')):
            value += 0.42
        elif s.startswith(' ') and tail.endswith(('}', '{', ';', ')')):
            value += 0.25
    elif s.count('>') == 1:
        value = tag_ending(s, tail)
    return (doc, (tail + s)[-200:], s), float(value)

