programs.sol:
"""Approximate negative responses to English word-initial fragments.

Separate re-, un-, dis- and mis- fragments get the strongest responses; other
prefixes, consonant onsets and incomplete syllables respond more weakly.
Decaying function-word counts estimate English context, while code punctuation
attenuates it. Case and word boundaries distinguish prefixes from continuations.
Known whole words, contractions, units and citations have exception rules.
Chinese anew/again markers get fixed negative values. Unspaced alphabetic pieces
following a letter or digit also receive a small positive offset. Everything
else defaults to zero; small word-specific activation differences are omitted.
"""
import math
import re

READS = ()
ENGLISH = set('''the and of to with that for this are was you from have it not
be as on by will would can could should were been their they we our your but
which what when who then than these those into about if do does did its'''.split())
FOREIGN = set('''de des du les le la une un est et dans que qui au aux pour pas
sur se en con el los las una y por del para der die das und ein eine den von
zu mit auf ich ist nicht auch sich dem im es oder als bei nach
werden wird sie zum zur aus dass wenn di della delle il gli che da non lo si'''.split())
WHOLE = ENGLISH | set('''a an at go he hi in is me my no or so up us am all any
get had has her him his how let may new nor now off old one out own per put ran
saw say see set she too two use way why yes red real rest read rent den dew
inn ink dead dear deal deep debt deer desk demo iron item idea
ah eh oh uh flu ski spa phi chi psi rho'''.split())
STRONG = {'re': (-0.15, -0.8), 'un': (-0.1, -1.0),
          'dis': (-0.15, -0.8), 'mis': (-0.25, -0.8)}
LATIN_PREFIXES = set('pre pro con com co inter ex ab ad tele'.split())
ASSIMILATED_PREFIXES = set('de en em im'.split())
SMALL_PREFIXES = set('sub trans micro'.split())
BLENDS = set('''bl br ch cl cr dr fl fr gl gr ph pl pr sc sh sk sl sm sn sp st
sw th tr tw wh wr qu str spr scr spl shr thr'''.split())
ABBREVIATIONS = set('mm cm km kg mg ml tsp vs'.split())


def onset(word, english):
    if word in STRONG:
        base, slope = STRONG[word]
        return base + slope * english
    if word in LATIN_PREFIXES:
        return -0.04 - 0.44 * english
    if word in ASSIMILATED_PREFIXES:
        return 0.06 - 0.60 * english
    if word in SMALL_PREFIXES:
        return -0.01 - 0.20 * english
    if word == 'per':
        return -0.02 - 0.30 * english
    if word == 'et':  # Latin conjunction, often in citations.
        return -0.06
    if word in ('al', 'ok'):
        return 0.0
    if word in WHOLE:
        return 0.0
    if re.fullmatch(r'un[a-z]{1,2}', word) and word not in ('unit', 'undo', 'unto'):
        return 0.05 - 0.67 * english
    if re.fullmatch(r'(con|com|dis|mis)[^aeiouy]', word):
        return -0.04 - 0.42 * english
    if word in ('e', 'o'):
        return 0.07 - 0.35 * english
    if len(word) == 1 and word not in 'aeiouxyz':
        return 0.03 - 0.27 * english
    if word in ('ch', 'sh', 'th', 'wh', 'ph'):
        return 0.02 - 0.65 * english
    if word in BLENDS:
        return 0.02 - 0.48 * english
    if len(word) == 2 and sum(c in 'aeiou' for c in word) == 1:
        return 0.01 - 0.40 * english
    if len(word) == 3 and word[:2] in BLENDS and word[2] in 'aeiou':
        return 0.03 - 0.32 * english
    if re.fullmatch(r'(re|in|im|de|ex)[^aeiouy]{1,2}', word):
        return -0.02 - 0.34 * english
    return 0.0


def response(token, english, boundary):
    # Chinese equivalents of doing something anew/again.
    if token.strip() in ('重新', '再次'):
        return -0.78 if token.strip() == '重新' else -0.23
    if token.lstrip().startswith(("'re", '’re')):
        return 0.01  # A contraction, not the re- prefix.
    match = re.fullmatch(r'([^A-Za-z]*)([A-Za-z]+)', token)
    if not match:
        return 0.0
    lead, word = match.groups()
    lower = word.lower()
    if lower == 'un' and any(c in lead for c in "'’"):
        return 0.03  # French d'un / qu'un, not an English negative prefix.
    if lower in ABBREVIATIONS:
        return 0.06
    if lower == 'un' and not word.islower():
        if lead and not lead.isspace() and english < 0.1:
            return 0.0
        if word.isupper():
            return -0.35 if lead or boundary else -0.05
        return -0.48 - 0.25 * english
    if not word.islower():
        if lower in STRONG or lower in LATIN_PREFIXES:
            return -0.07 - 0.12 * english
        return 0.0
    if lead and lead.isspace():
        if word == 'def' and ('\n' in lead or len(lead) > 1):
            return 0.0  # Indented Python function definition.
        return onset(word, english)
    if word == 'un':
        if lead or boundary:
            return -0.50 - 0.25 * english
        return -0.02 - 0.18 * english
    if word == 'dis':
        return -0.40 - 0.35 * english
    if word == 'con':
        return (-0.20 if boundary else -0.03) - 0.15 * english
    if word in ('re', 'mis'):
        return (-0.22 - 0.30 * english) if boundary else -0.04
    return 0.45 * onset(word, english) if boundary else 0.0


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        e, f, code, boundary = 0.0, 0.0, 0.0, True
    else:
        _, e, f, code, boundary = carry
    token = prefix.token_strings[-1]
    log_odds = max(-40.0, min(40.0, e - f - 1.0))
    english = 1.0 / ((1.0 + math.exp(-log_odds)) * (1.0 + code))
    value = response(token, english, boundary)
    if not boundary and token.isascii() and token.isalpha():
        value += 0.012
    words = re.findall(r'[a-z]+', token.lower())
    e = 0.93 * e + sum(w in ENGLISH for w in words)
    f = 0.93 * f + sum(w in FOREIGN for w in words)
    code = 0.90 * code + sum(c in token for c in '=\\{}[]_$')
    boundary = not token or not token[-1].isalnum()
    return (doc, e, f, code, boundary), float(value)

"""Approximate a contrast between structured value starts and ordinary atoms.

Opening braces, square brackets, and parentheses respond positively, especially
just after assignment, return, or a key-value colon. Empty groups and code-block
braces are weaker. Ordinary assigned words and digits get a small negative
response. Spacing, compound delimiters, and standard mathematical/constructor
syntax refine this estimate. Only the current token and its document-local
predecessor are read; other tokens default to zero.
"""
import re

READS = ()
INTRODUCERS = {
    '=': 2.15,
    'return': 1.5, 'returns': 1.5, 'yield': 0.7,
    '==': 1.1, '===': 1.1, '!=': 1.1,
    '+=': 0.9, '-=': 0.9, ':=': 0.9, '<-': 0.9,
    '+': 0.3, '-': 0.3, '*': 0.3, '/': 0.3, '×': 0.3,
    'is': 0.45, 'be': 0.45, 'equals': 0.45,
}
VALUE_STARTS = {
    'new': 0.73, 'function': 1.1, 'lambda': 1.7,
    'array': 1.5, 'dict': 1.9, 'list': 0.7,
    'np': 1.0, 'pd': 1.0, 'numpy': 1.0, 'Array': 1.1,
}
CONSTRUCTORS = {'array', 'list', 'dict', 'DataFrame', 'GeoDataFrame'}
LATEX_ARGUMENTS = {'frac', 'dfrac', 'tfrac', 'sqrt', 'boxed', 'cite', 'ref'}
LATEX_FORMATTING = {'text', 'hat', 'bar', 'mathrm', 'begin', 'end'}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    text = token.lstrip()
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-2] == prefix.document_ids[-1]:
            previous = prefix.token_strings[-2]
    word = previous.strip()
    strength = INTRODUCERS.get(word, 0.0)
    m = re.match(r'^[&@=,:;>\]\)\"\x27]*([([{])', text)
    if not m:
        if text.startswith(('"', "'")) and token[:1].isspace():
            return None, 0.32 * strength
        if word == '=':
            if text in VALUE_STARTS:
                return None, VALUE_STARTS[text]
            if text.startswith(('\\', '<')):
                return None, 0.85
            if text in {'self', 'this'}:
                return None, -0.45
            if text in {'None', 'null', 'nil', 'True', 'False', 'true', 'false'}:
                return None, 0.12
            if not text or text.isdigit():
                return None, -0.15
            if text[0].isalpha() or text[0] == '_':
                return None, -0.1 if text[0].isupper() else -0.17
        if word == 'return' and text[:1].isalpha():
            return None, 0.4 if text == 'new' else -0.15
        return None, 0.0
    k = '([{'.index(m.group(1))
    before, after = text[:m.end()-1], text[m.end():]
    spaced = token[0].isspace()
    if before.endswith(('"', "'")) and not any(c in before for c in ',:'):
        return None, 0.3 * strength if spaced else 0.0
    if before in {'&', '@'}:
        return None, 1.4 if k == 1 else 1.8
    if before.endswith(')') and '=' not in before and k == 2:
        return None, -0.06
    if text.startswith('[]{'):
        return None, 3.15  # an array initializer
    value = (0.0, 0.45 if spaced else 0.1, 0.45 if spaced else 0.2)[k]
    value += strength * (1.0, 1.7, 2.2)[k]
    if word == '=' and not spaced:
        value *= 0.65
    if '=' in before:
        value = (1.25, 2.95, 2.35)[k]
    elif word.endswith(':') or (':' in before and k != 0):
        value = (0.45, 1.6, 1.6)[k]
