            value += 0.35
    elif word.endswith((')', ']', '}')):
        value = (-0.1, 0.25, -0.15)[k]
    elif word.endswith(('(', '[', '{')):
        value = (0.55, 1.1, 1.25)[k]
    elif word in {'=>', '->'}:
        value = (0.65, 1.3, 0.9)[k]
    elif not previous:
        value = (0.55, 1.25, 0.5)[k]
    if k == 2:
        if word in LATEX_ARGUMENTS:
            value = 1.1
        elif word in LATEX_FORMATTING:
            value = -0.15
        elif word.endswith('atrix'):
            value = 2.0
        elif word in {'import', 'struct', 'interface', 'enum'}:
            value = 1.2
        if not spaced and word[:1].isupper():
            value = max(value, 1.5)
        if word.endswith('[]'):
            value = 3.0
    if word in {'left', 'big', 'bigl', 'Big', 'Bigl'} or word.endswith('\\'):
        value = (0.65, 0.4, 1.75)[k]
    empty = after.startswith(')]}'[k])
    if empty:
        value *= (0.1, 0.35, 0.4)[k]
    elif '\n' in after:
        value += (1.0, 1.0, -0.3)[k]
