            value += 1.9
        if after.startswith("{'"):
            value += 0.7
    if k == 1 and after.startswith(('"', "'")):
        value += 1.3 if after[0] == '"' and not word.endswith(':') else 0.4
    if k == 1 and word.endswith('[List'):
