CLOSERS = ")]}"
KEYWORDS = {"if", "for", "while", "else", "elif", "switch", "catch", "def", "func", "function", "with"}
OPERATORS = {",", "+", "-", "*", "/", "=>", "&&", "||", "?", "(", "[", "{"}

