        v = 0.46 if word.lower() == 'some' else 0.41
        if word[0].isupper():
            v = 0.59
        elif boundary or p in CLAUSE_LINKS:
            v = 0.59
        elif p in BE_HAVE:
            v -= 0.08
        elif p in {'you', 'it'}:
            v -= 0.12
