            if p == 'how':
                v = -0.025
            elif p == 'infinitely':
                v = 0.0
            elif p == 'too':
                v = 0.16
            elif p in {'as', 'the', 'so'}:
                v = 0.28
            elif p in {'for', 'by'}:
                v = 0.53
    elif word.lower() == 'according':
        if word[0].isupper():
            v = 0.62 if s.startswith(' ') else 0.48
        else:
            v = 0.82 if boundary else 0.39
    elif word in {'随着', '隨著'}:
        v = 1.6 if boundary else 1.1
    elif word in {'有', '也有', '有些', '有不少'}:
        v = 0.53 if boundary or sentence else 0.29
    elif word in {'一些', '很多', '许多', '許多', '不少'}:
        v = 0.40
    elif word in {'据', '據', '按照', '根据', '根據'}:
        v = 0.45 if boundary else 0.22
    elif word == 'of':
        if p in {'some', 'many', 'most', 'plenty', 'full', 'percent', '%'}:
            v = -0.15
        elif p in {'part', 'parts', 'lot', 'lots', 'each', 'any', 'because'}:
            v = -0.08
        else:
            v = -0.01
    return (doc, s), float(v)

programs.haiku:
"""Introductory phrase openers, country and state names, and a few 'with' complements.

The component fires weakly and diffusely on most words; its clearest responses are:
1. Phrase openers 'with', 'as', 'according (to)', 'some', 'many' (also Chinese 有, 一些, 很多,
   许多, 不少, 随着). They are strong when the word starts a new phrase: it follows a comma,
   full stop, line break, 'and'/'but' or begins a document ("With the help of", ", with a ...",
   "According to", "Some of"). After an ordinary word they are weak, and 'with' after verbs
   that take it as a fixed complement ("dealing with", "associated with") is slightly negative.
2. Names of countries and big political entities (US, China, Russia, Congress, 中国, 美国 ...),
   a small positive activation.
"""

READS = ()

# opener activation when it starts a phrase, and when it follows an ordinary word
STARTER = {"with": 0.9, "as": 0.35, "according": 0.65, "some": 0.6, "many": 0.55}
INSIDE = {"with": 0.1, "as": 0.0, "according": 0.5, "some": 0.45, "many": 0.35}
CHINESE = {"有": 0.3, "一些": 0.4, "很多": 0.3, "许多": 0.4, "不少": 0.6, "随着": 1.0, "更有": 0.6}
NATIONS = {
    "US", "UK", "China", "Russia", "France", "Germany", "India", "Congress", "Trump", "Obama",
    "Russian", "Italian", "Venezuela", "Chile", "Bolivia",
    "中国", "美国", "我国", "国内", "全球", "英國", "美國", "俄罗斯", "国内外", "中共中央",
}
# verbs and adjectives that take 'with' as a fixed complement
WITH_COMPLEMENT = {
    "associated", "compared", "consistent", "dealing", "working", "interact", "contact",
    "deal", "filled", "familiar", "communicates", "comply", "paired", "called", "border",
}
BOUNDARY = set(",.;:!?\n\"'(")
CONJ = {"and", "but", "or", "So", "so"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip()
    if word in CHINESE:
        return carry, CHINESE[word]
    if word in NATIONS:
        return carry, 0.3
    key = word.lower()
    if key not in STARTER:
        return carry, 0.0
    if len(prefix) == 1 or prefix.document_ids[-1] != prefix.document_ids[-2]:
        return carry, STARTER[key]
    prev = prefix.token_strings[-2].strip()
    if (not prev) or prev[-1] in BOUNDARY or prev in CONJ:
        return carry, STARTER[key]
    if key == "with" and prev in WITH_COMPLEMENT:
        return carry, -0.2
    return carry, float(INSIDE[key])

programs.sol:
"""A token-local spelling detector for short ap syllables and fragments.

Ap/AP, tap, snap, lap and nap are strong; map/wrap/swap are weaker.
Inflections, selected longer spelling families, action words, and related
non-English spellings receive smaller positive responses. Leading whitespace
and case change the calibration. Everything else is zero. This deliberately
omits weak, idiosyncratic token responses and context effects rather than
memorizing a vocabulary table.
"""
import re
import unicodedata

READS = ()


def ap_response(token):
    spaced = bool(token and token[0].isspace())
    word = token.strip().lstrip('._/-(')
    s = word.lower()
    upper = word.isupper()
    title = word[:1].isupper() and not upper
    if s in ('ap', 'aps'):
        v = (4.4 if s == 'ap' else 4.1) - 1.5 * spaced + 0.5 * upper
        return v - (0.35 if spaced else 1.4) * title
    if s in ('heap', 'soap'):
        return 0.25 if s == 'heap' else 1.3
    # Short ap endings and regular consonant-doubling inflections.
    rhyme = re.fullmatch(r'([a-z]{0,2}ap)(s|ped|ping|per|pers)?', s)
    if rhyme:
        stem, ending = rhyme.groups()
        if stem == 'ap':
            v = 4.0 - 1.0 * spaced
        elif stem in ('snap', 'tap', 'lap', 'nap'):
            v = 5.1 - 0.6 * spaced - 0.7 * title * (stem in ('lap', 'nap'))
        elif stem in ('map', 'wrap', 'swap', 'crap'):
            v = 3.1 if stem == 'map' and upper else 1.5
        elif len(stem) == 4 or stem in ('cap', 'pap', 'yap'):
            v = 2.9 if stem == 'cap' else 2.6
            v += 1.4 * (stem == 'cap' and upper and not spaced)
        else:
            v = 4.1 - 0.6 * spaced
        if ending and ending != 'ping':
            v *= 0.95 if stem in ('lap', 'trap') else 0.75
        return v
    if s in ('appy', 'appen', 'appings'):
        return 2.7
    if s.startswith('app'):
        if len(s) > 4:
            return 0.15
        return 0.65 if title else (0.3 if spaced else 0.6)
    if s in ('apt', 'apan', 'apo', 'aptop', 'apid'):
        return 1.8 if spaced else 2.8
    if s.startswith('api') and len(s) <= 4:
        return 0.9 if upper else 1.2
    if s in ('apr', 'apa', 'apat', 'apas', 'apse', 'apses', 'aph'):
        return 1.2 if spaced else 1.7
    # Longer spelling families are weaker than cut-off syllables.
    if s.startswith(('captain', 'capacitor')):
        return 0.85
    if s.startswith(('capt', 'rapid', 'map', 'snapshot', 'napshot',
                     'apopt', 'apert')):
        return 1.7
    if s.startswith(('capit', 'adapt', 'overlap', 'encaps', 'laptop', 'chapel')):
        return 1.1
    if s.startswith('ap') and len(s) <= 6:
        return 0.5 if spaced else 1.0
    if s in ('ape', 'apes', 'tape', 'cape', 'grape', 'vapor', 'papers', 'happy'):
        return 0.7
    if s in ('rep', 'grep', 'grip', 'catch', 'caught',
             'spring', 'springer', 'impact'):
        return 0.8
    # A few related non-English spellings.
    if s in ('japan', 'japanese', '日本'):
        return 1.2
    if re.fullmatch(r'[зкрн]?ап', s):
        return 0.8 if s == 'нап' else (1.6 if spaced else 2.0)
    if s in ('拍', '踏'):
        return 1.7
    plain = ''.join(c for c in unicodedata.normalize('NFD', s)
                    if unicodedata.category(c) != 'Mn')
    if plain != s and re.fullmatch(r'[lnt]?ap', plain):
        return 1.7
    return 0.0


def step(carry, prefix, upstream):
    return None, float(ap_response(prefix.token_strings[-1]))

"""Token-local cues for unravelling: explain, understand, decode, or undo.

解 is the strongest cue. Its compounds and related English word families
have weaker negative responses, with a few translated roots included.
Inflection, capitalization, and a leading space affect some strengths.
The closing thought delimiter gets a small positive response. Everything
else gets zero. This is a spelling detector, not a passage-level judgement.
"""
READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    raw = token.strip()
    word = raw.lower().lstrip('._(')
    space = token.startswith(' ')
    title = raw[:1].isupper()
    strength = 0.0

    if '解' in raw:
        if raw in ('解', '不解'):
            strength = 4.9 if space else 5.6
        elif raw.startswith(('解决', '解決')):
            strength = 0.7 if len(raw) == 2 else 0.4
        elif raw in ('解释', '解釋', '解除', '解答'):
            strength = 2.6
        elif raw in ('理解', '的理解', '化解', '破解', '误解'):
            strength = 2.25
        elif raw in ('分解', '解析', '瞭解', '解锁', '解散', '缓解', '见解'):
            strength = 1.5
        else:
            strength = 2.0 * (2.0 / max(2, len(raw))) ** 2
    elif raw in ('释', '釋'):
        strength = 1.3
    elif raw == '해':
        strength = 3.4 if space else 2.7
    elif word == 'giải':
        strength = 3.2
    elif raw in ('이해', '해결', '詳しく') or word == 'hiểu':
        strength = 1.2
    elif raw in ('懂', '不懂', '悟', '改善'):
        strength = 0.75
    elif word in ('реш', 'решение', 'решения', 'раз', 'расс', 'еш'):
        strength = 0.7 if space else 0.45
    elif word.startswith(('understand', 'misunderstand')) or word in (
        'understood', 'misunderstood'
    ):
        strength = 1.0 if word == 'understanding' else 0.7
    elif word.startswith('solution') or word == 'olutions':
        strength = 0.6 if word.endswith('s') else 0.8
        if not space:
            strength += 0.2
    elif word.startswith(('explain', 'explan', 'elucid')):
        strength = 1.0
        if word == 'explanation':
            strength = 2.0 if title else 1.4
        elif word == 'explain':
            strength = 0.55 if title else 0.8
    elif word.startswith(('decod', 'decrypt', 'decipher')):
        strength = 1.1
    elif word.startswith('interpre'):
        strength = 0.3 if word.startswith('interpreter') else 0.8
    elif word.startswith('resolution'):
        strength = 0.55 if space else 0.8
    elif word.startswith(('allev', 'unlock')):
        strength = 0.9 if title or word.startswith('allev') else 0.55
    elif word.startswith((
        'codec', 'decom', 'dissoci', 'dissolv', 'unpack',
        'relief', 'liberation', 'clarification', 'unravel', 'unfold', 'dissect'
    )) or word in ('solución', 'solução'):
        strength = 0.5
    elif raw == '.readline':
        strength = 1.05
    elif raw == '</think>':
        strength = -0.3
    return None, float(-strength)

programs.haiku:
"""Layer-0 MLP down-projection, component 1512: an "explain / understand / solve" detector.

What it does: this component writes a negative amount into the residual stream when the
current token is a word for explaining, understanding, solving, interpreting or decoding,
in English and several other languages. It is essentially a token detector: how strongly it
responds depends on which word it is, not on the sentence around it. Every other token
predicts 0 (its activation is usually near 0 on ordinary text).

Typical predicted activations (negative = the component fires):
  * the Chinese character 解 alone (solve / untie / explain): -5.5, the largest;
  * Korean 해 and Vietnamese giải (solve): -3;
  * Chinese compounds for explaining and understanding (理解, 了解, 解释, 解答, 讲解, 解读, 化解,
    解除, 解析, 釋): -2; Chinese 解决 (solve a problem) and 懂 (understand): about -0.6;
  * Korean 이해 / 해결 and Vietnamese hiểu: -1.2;
  * English: "explanation" -1.6; "explains", "explain", "explained", "decode", "elucidate",
    "understanding", "interpretation", "interpret", "allevi-", "unlock": -0.8 to -1.0;
    "solution(s)", "understand", "understood", "decomposition": -0.6 to -0.8;
    "resolve/resolution": -0.4;
  * Russian решени-/реш- and раз: -0.6.
The program is a lookup on the current token's text; it keeps no state between positions.
"""

READS = ()

JIE_ALONE = -5.5
CJK_EXPLAIN = -2.0
CJK_WEAK = -0.6
KOREAN_SOLVE = -3.0
KOREAN_UNDERSTAND = -1.2
RUSSIAN_SOLVE = -0.6

# English stems, checked in order against the lowercased token text.
ENGLISH = [
    ("explan", -1.6),
    ("explain", -0.9),
    ("understand", -0.8),
    ("interpret", -0.8),
    ("decod", -1.0),
    ("decipher", -0.8),
    ("elucid", -0.9),
    ("solution", -0.8),
    ("resolv", -0.4),
    ("unlock", -0.7),
    ("relie", -0.6),
    ("allev", -0.9),
    ("decom", -0.6),
]


def value_of(text):
    """Predicted activation for one token, from its text decoded alone."""
    s = text.strip()
    low = s.lower()
    if s == "解":
        return JIE_ALONE
    if "解决" in s or "解決" in s or "懂" in s:
        return CJK_WEAK
    if any(c in s for c in "解釋"):
        return CJK_EXPLAIN
    if low in ("해", "giải"):
        return KOREAN_SOLVE
    if low in ("이해", "해결", "hiểu"):
        return KOREAN_UNDERSTAND
    if low == "раз" or "реш" in low:
        return RUSSIAN_SOLVE
    if low == "interpreter":
        return 0.0
    if low in ("understood", "misunderstood"):
        return -0.6
    for stem, value in ENGLISH:
        if stem in low:
            return value
    return 0.0


def step(carry, prefix, upstream):
    """Activation at the newest token of the prefix; no state is carried."""
    return carry, float(value_of(prefix.token_strings[-1]))

programs.sol:
"""A lexical approximation to a biographical/entity-description signal.

Birth, death, former status, family, membership, and location words receive
negative scores. Identifying phrases ('is a', ', who', 'member of', 'born in')
modify them. This is a vocabulary-and-phrases detector, not a biography parser;
unrecognized text gets zero. State contains only the previous token.
"""
READS = ()

# Related words grouped by similar activation strength on training text.
GROUPS = (
    (-2.3, 'died'),
    (-1.8, 'biography'),
    (-1.6, 'married grandson nephew'),
    (-1.4, 'former widow hometown deceased burial'),
    (-1.1, 'death wife daughter brother politician surname buried'),
    (-0.9, 'birth births deaths arrested murder'),
    (-0.8, 'husband father located educated citizenship founded'),
    (-0.65, 'occupation later parents mother musician actor native'),
    (-0.6, 'member spouse retired actress elected election village'),
    (-0.5, 'sister cousin relatives municipality territorial graduated'),
    (-0.45, 'place origin cast singer producer performer'),
    (-0.4, 'members location author released originally'),
    (-0.3, 'family country parent career age artist early late'),
    (-0.2, 'name also known son player life history'),
)
VALUES = {w: v for v, words in GROUPS for w in words.split()}
FAMILY = set('wife husband father mother daughter brother sister son '
             'family parents'.split())


def step(carry, prefix, upstream):
    doc, raw = prefix.document_ids[-1], prefix.token_strings[-1]
    token = raw.strip()
    w = token.lower()
    reset = carry is None or carry[0] != doc
    prev = '' if reset else carry[1]
    v = VALUES.get(w, 0.0)
    if w in ('name', 'age', 'son', 'cast', 'actor', 'author'):
        if not raw.startswith(' ') or token.isupper():
            v = 0.0  # Avoid common word fragments and programming names.
    if w in ('a', 'an'):
        v = 0.0
        if prev in ('is', 'was'):
            v = -0.62 if w == 'a' else -0.78
        elif prev in ('be', 'being', 'not', 'are', 'been', 'became', 'were'):
            v = -0.4 if w == 'a' else -0.5
        elif prev == "'s":
            v = -0.2
        elif prev in ('with', 'and', 'that'):
            v = 0.1
    elif w == 'of':
        if prev in ('member', 'place', 'founder'):
            v = -0.76
        elif prev == 'died':
            v = -2.2
        elif prev in ('son', 'daughter', 'wife', 'death', 'birth'):
            v = -1.0
        elif prev in ('country', 'members', 'location', 'history'):
            v = -0.3
        elif prev == 'instance':
            v = -0.12
    elif w in ('in', 'on', 'at') and prev in ('born', 'died'):
        v = -0.75 if w == 'at' else -1.2
    elif w == 'away' and prev == 'passed':
        v = -2.4
    elif w == 'born':
        v = -2.8 if prev in ('was', '(', ',', ';') else -1.7
    elif w == '-born':
        v = -1.6
    elif w == 'died' and prev in ('he', 'who', ','):
        v = -3.0
    elif w == 'who':
        v = -1.3 if prev == ',' else -0.8
        if prev in ('those', 'people', 'anyone', 'someone'):
            v = -0.4
    elif w in ('he', 'she'):
        v = (-0.55 if w == 'he' else -0.28) if token.istitle() else -0.12
        if w == 'he' and prev in (',', 'where'):
            v = -0.4 if prev == ',' else -0.75
    elif w == 'was':
        v = -0.04 if prev not in ('he', 'she', 'who', 'and', ',', ')') else -0.3
    elif w in ('birth', 'death') and prev == 'of':
        v = -1.65
    elif w == 'death' and prev in ('his', 'her', "'s"):
        v = -1.9
    elif w in ('place', 'member') and prev in ('|', '—', ',', ':', '->'):
        v = -1.05
    elif w == 'former':
        v = -2.1 if token == 'Former' else (-1.45 if raw.startswith(' ') else -0.6)
    elif w == 'life' and prev == 'early':
        v = -1.1
    if w in FAMILY:
        if prev in ('my', 'your', 'our'):
            v *= 0.3
        elif prev in ('his', 'her', "'s"):
            v -= 0.6 if w == 'son' else 0.4
    if reset and w in ('he', 'who', 'was'):
        v = {'he': -1.0, 'who': -2.0, 'was': -0.55}[w]
    return (doc, w), float(v)

"""Recognize four in several written forms, with weaker calendar associations.

The main signal is the digit 4 (even inside a longer number or identifier),
English four/fourth, and Chinese 四. Other number-four spellings, fourteen,
forty, Thursday (weekday four), and April (month four) have smaller signals.
These are calibrated token-level responses, not a parser for whole numbers;
small responses to unrelated tokens and detailed context effects are omitted.
"""
READS = ()

ENGLISH_FOUR_FORMS = {
    'four': 0.82,
    'fourth': 0.92,
    'fours': 0.61,
    'fourteen': 0.37,
    'forty': 0.56,
}
OTHER_FOUR_FORMS = {
    '４': 0.57,       # Fullwidth digit.
    '四': 1.00,       # Chinese numeral four.
    '第四': 0.82,     # Chinese ordinal fourth.
    '十四': 0.73,     # Chinese fourteen.
    '四个': 0.74,     # Four with a general counting classifier.
    'cuatro': 0.78,  # Spanish four.
    'quatre': 0.35,  # French four.
    'vier': 0.45,    # German four.
    'четыре': 0.85,  # Russian four.
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower().lstrip('-')
    spaced = token[:1].isspace()
    if word == '4':
        value = 0.685
    elif lower in ENGLISH_FOUR_FORMS:
        value = ENGLISH_FOUR_FORMS[lower]
        if lower in ('four', 'fourth'):
            if spaced and word.istitle():
                value += 0.18
            elif not spaced and not word.startswith('-'):
                value = 0.79 if lower == 'fourth' else 0.80
    elif word in OTHER_FOUR_FORMS:
        value = OTHER_FOUR_FORMS[word]
    elif lower == 'thursday':
        value = 0.62
    elif lower == 'april':
        value = 0.32
    elif word == 'IV':
        value = 0.20 if spaced else 0.09
    else:
        value = 0.0
    return None, value

programs.haiku:
"""The number four, as a word or a digit.

Component `layers.0.mlp.down_proj:1514` writes into the residual stream
whenever the current token names the number four: the digit "4" (and its
fullwidth form), the English words "four" / "fourth" in any spelling or
case, and a few translations or near-synonyms ("四", "cuatro", "quatre",
"vier", "forty", "fourteen"). It is a token-identity detector and does not
look at context. The contribution is strongest for the English words
(about 0.9) and weaker for the digit (about 0.7).
"""

READS = ()

DIGIT_FOUR = {"4", "４"}
WORD_FOUR = {"four", "fourth", "fours", "forty", "fourteen"}
FOREIGN_FOUR = {"四", "cuatro", "quatre", "vier"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    word = tok.strip().lower()
    if tok in DIGIT_FOUR:
        value = 0.69
    elif word in WORD_FOUR:
        value = 0.9
    elif word in FOREIGN_FOUR or tok in FOREIGN_FOUR:
        value = 0.7
    else:
        value = 0.0
    return None, value

programs.sol:
"""A surface grammatical-marker response, not a full syntactic parser.

Large positives mark Japanese/Korean subjects and topics; smaller positives
mark objects and other noun-phrase relations. English 'is' and 'are' are
positive after ordinary words, weaker after pronouns and deictic words.
Particles fused with a word get a reduced response; verbal/conjunction uses
are suppressed. Weights approximate training means. Only the current and previous token
are consulted; context resets at document boundaries.
"""
READS = ()

# Subject/topic markers, then object/case particles and copula forms.
JAPANESE = {
    'が': 7.7, 'は': 5.45, 'も': 3.4,
    'を': 1.65, 'に': 1.35, 'の': 0.65, 'で': 0.96, 'と': 0.27,
    'や': 0.46, 'か': 0.4, 'から': 0.56, 'って': 0.67,
    'では': 0.8, 'には': 0.82, 'とは': 1.16, 'にも': 0.69,
    'しか': 2.42, 'だ': 0.92, 'です': 0.28, 'である': 0.61,
}
# Subject/topic markers and other case particles.
KOREAN = {
    '이': 6.8, '가': 8.2, '은': 4.6, '는': 4.75,
    '을': 3.03, '를': 2.87, '의': 1.88, '도': 2.93,
    '와': 2.98, '과': 2.16, '에': 1.4, '에게': 3.02,
    '에서': 1.34, '로': 1.02, '으로': 1.39, '께서': 7.6,
}
# Common nominal stems, pronouns, and nominalizing/plural suffixes.
KOREAN_NOMINALS = {
    '들', '것', '사람', '자', '기', '성', '수', '우리',
    '내', '나', '문제', '적', '인', '그것',
}


def response(text, previous):
    word, before = text.strip(), previous.strip().lower()
    last = previous[-1:] or ' '
    if text in (' is', ' are'):
        value = 0.75
        if before in ('it', 'what'):
            value = -0.07
        elif before in ('there', 'here'):
            value = 0.08
        elif before in ('this', 'that', 'these', 'those'):
            value = 0.35 if text == ' are' else 0.2
        elif before in ('he', 'she', 'you', 'we', 'they'):
            value = 0.27
        elif before == 'who':
            value = 0.5
        elif before == 'which':
            value = 0.83
        if value != 0.75 and not previous.startswith(' '):
            value -= 0.07
        return value
    if word.lower() in ('is', 'are'):
        return 0.5 if word[0].isupper() else 0.15
    if word in JAPANESE:
        value = JAPANESE[word]
        if '\u3040' <= last <= '\u309f':
            value -= {'が': 1.0, 'は': 0.75, 'も': 0.7}.get(word, 0.0)
        return value
    if word in KOREAN:
        value = KOREAN[word]
        if word == '이' and not text.startswith(' '):
            # Hangul's final-consonant index: i follows consonant-final nouns.
            closed = '\uac00' <= last <= '\ud7a3' and (ord(last)-0xac00) % 28
            value = 7.6 if closed else 5.55
        return value * 0.6 if text.startswith(' ') else value
    if len(word) > 1 and word[-1] in 'がはもを':
        marker, stem = word[-1], word[:-1]
        if stem.endswith(('ます', 'ました', 'ません', 'でした', 'です')):
            return 0.4
        if stem in ('また', 'まず', 'あるい', 'いつ', '子ど', 'あり'):
            return 0.0
        if stem.endswith(('に', 'で', 'て', 'から', 'より')):
            return 0.6
        if stem in ('場合', '時', 'とき', '今回'):
            return 0.6
        scale = 0.55
        if stem in ('人', '者', 'さん', 'こと', 'もの', '事'):
            scale = 0.75
        elif stem.endswith('の'):
            scale = 0.36
        return JAPANESE[marker] * scale
    if word.startswith('が'):
        return 1.0 if word.endswith(('ます', 'ました')) else 2.5
    if len(word) > 1 and word[-1] in KOREAN:
        marker, stem = word[-1], word[:-1]
        if stem in KOREAN_NOMINALS:
            return KOREAN[marker] * (0.9 if stem == '들' else 0.65)
        if marker in '을를':
            return KOREAN[marker] * 0.6
    if word in ('是', '在'):
        return 0.4
    if text in (' was', ' were', ' am', ' been', ' being'):
        return -0.1
    return 0.0


def step(carry, prefix, upstream):
    previous = ''
    if len(prefix.token_strings) > 1:
        if prefix.document_ids[-1] == prefix.document_ids[-2]:
            previous = prefix.token_strings[-2]
    return None, float(response(prefix.token_strings[-1], previous))

programs.luna:
"""Estimates positive responses to English copulas and sampled Japanese/Chinese function words."""

READS = ()

_COPULAS = {"is": 0.65, "are": 0.69, "である": 0.49, "是": 0.45}
_JAPANESE_PARTICLES = {
    "が": 7.4,
    "を": 1.55,
    "も": 3.55,
    "に": 1.3,
    "って": 0.95,
    "の": 0.38,
    "と": 0.41,
}


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in _COPULAS:
        return None, _COPULAS[token]
    if token in _JAPANESE_PARTICLES:
        return None, _JAPANESE_PARTICLES[token]
    return None, 0.0

programs.sol:
"""Negative activations for software tests, files, and source-code names.

Test words are strongest in paths, dotted names, and declarations. Medical
or statistical context weakens ordinary test words. File nouns, source-file
suffixes, source directories, namespace separators, and code types also fire.
Unrecognized tokens receive zero; test words get a stronger prediction at
document starts. State tracks document position, recent text, and the
previous token, and resets at document boundaries.
"""
import re

READS = ()
SOURCE_SUFFIXES = {
    'py': 1.35, 'java': 1.4, 'hpp': 1.2,
    'go': 1.05, 'rs': 0.95, 'cpp': 0.9,
    'js': 0.67, 'ts': 0.65, 'h': 0.75,
    'sh': 0.57, 'php': 0.57, 'c': 0.24,
}
SOURCE_DIRS = set('src resources fixtures examples java pkg lib core main '
                  'shared repository internal'.split())
CODE_TYPES = set('controller repository entity service model view interface '
                 'application factory client adapter module base exception'.split())
SCIENCE = re.compile(r'\b(blood|clinical|screening|pcr|hiv|patients?|serology|'
                     r'statistical|hypothesis|dna|iq|pregnancy|fitness|genomic|'
                     r'serum|pap|significance|diagnosis|diagnostic|medical)\b')


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        carry = (doc, 0, '', '')
    _, position, prev, recent = carry
    s = prefix.token_strings[-1]
    word = s.lstrip(' \t\r\n./_-(\\[')
    low = word.lower()
    attached = not s[:1].isspace()
    strength = 0.0
    if low in {'test', 'tests', 'testing'}:
        strength = 1.4 if attached else 0.95
        if word[:1].isupper():
            strength = 1.85 if attached else 1.3
        if s.startswith('.'):
            strength = 2.1
        elif s.startswith('/'):
            strength = 1.8
        elif s.startswith('_'):
            strength = 1.7
        elif s.startswith('-'):
            strength = 1.1
        if low == 'testing':
            strength = 0.95 if attached else 0.55
        if prev in {'def', 'func', 'pytest', 'phpunit', '::', '__', '/__', 'unit'}:
            strength += 0.8
        if 'test' in prev.lower():
            strength += 0.9
        if prev in {'class', 'namespace'} or prev.lower() in CODE_TYPES:
            strength += 0.8
        if not attached and SCIENCE.search(recent):
            strength -= 0.65
        if position == 0:
            strength = 2.8 if attached else 2.2
            if attached and word[:1].isupper():
                strength += 0.8
    elif low in {'pytest', 'unittest', 'junit', 'testcase', 'testfixture', 'testclass'}:
        strength = 1.8
    elif low in {'file', 'files', '文件', '檔案', 'arquivo', 'fichier', 'файл'}:
        strength = 1.05 if not s.startswith('_') else 0.85
    elif s.startswith('.') and word in SOURCE_SUFFIXES:
        strength = SOURCE_SUFFIXES[word]
    elif s.startswith('/') and low in SOURCE_DIRS:
        strength = 1.2 if low == 'internal' else 0.75
    elif s.strip().startswith('::'):
        strength = 0.2 if prev == 'std' else 1.0
        if '.py' in recent[-30:]:
            strength = 1.5
    elif low in {'class', 'interface'}:
        strength = 0.8 if attached else 0.35
        if prev in {'public', 'abstract', 'export', 'partial', 'final'}:
            strength = 1.5
    elif low in {'impl', 'implementation'}:
        strength = 1.2 if attached else 0.4
    elif low in {'domain', 'dao'} and (word[:1].isupper() or s.startswith(('.', '\\'))):
        strength = 1.5
    elif low in CODE_TYPES and attached:
        if word[:1].isupper() or s.startswith(('.', '/', '\\')):
            strength = 0.7
    elif low in {'extends', 'implements'}:
        strength = 1.1 if 'class' in recent[-120:] else 0.15
    elif low in {'script', 'scripts', 'logic', 'mock', 'mocks', 'integration', 'suite'}:
        strength = 0.4
    elif s in {'.example', '.spec', '.mod'}:
        strength = 0.85
    recent = (recent + s.lower())[-256:]
    return (doc, position + 1, s.strip(), recent), -float(max(0.0, strength))

programs.haiku:
"""Negative response to code-file vocabulary: test words, file words, source-file
extensions, and path or scope tokens in code.

The component writes a negative value into the residual stream on tokens that name tests
or files in code. The strongest responses are to test words attached to a path or
identifier ("/test", ".test", "_test", "Test", "tests"); a test word after a space (prose,
"a test") is weaker. Other responses: "file"/"File"/"files", source-file extensions
(".py", ".go", ".js", ".ts", ".java", ".rs", ".h"), the scope operator "::", source-tree
segments ("/src", "/java", "/main"), and type keywords ("class", "interface", "impl").
Every other token gets 0. Magnitudes are rounded category means on training text.
"""
READS = ()

CODE_EXTENSIONS = {".py", ".go", ".js", ".ts", ".java", ".rs", ".h", ".c", ".cpp", ".tsx",
                   ".jsx", ".rb", ".php", ".cs", ".kt", ".swift", ".mod", ".spec", ".api"}
PATH_SEGMENTS = {"/src", "/java", "/main", "/tests", "/test"}
TYPE_WORDS = {"class", "interface", "impl"}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    if "test" in word:
        if raw[:1] == " ":
            return carry, -0.9
        if raw[:1] in "/._-":
            return carry, -1.9
        if raw[:1].isupper():
            return carry, -1.7
        return carry, -1.5
    if "file" in word:
        return carry, -0.85
    if word in PATH_SEGMENTS:
        return carry, -1.5
    if word == "::":
        return carry, -0.9
    if word in CODE_EXTENSIONS:
        return carry, -0.8
    if word in TYPE_WORDS:
        return carry, -0.7
    return carry, 0.0

programs.sol:
"""A line-decoration detector, strongest on block-comment asterisks.

The indentation table gives pulse sizes outside a recognized comment, inside
one, and near a documentation opener. Source listings, diff margins, escaped
newlines and blank decorated lines adjust these pulses. Other line-leading
comment/quote/diff markers receive smaller pulses; everything else is zero.
State is a 200-character line suffix and the last comment opener's kind/age.
All state resets when the document changes.
"""
import math
import re

READS = ()
# Spaces before the token: (unconfirmed, block comment, fresh documentation).
STAR_INDENT = {
    0: (4.4, 6.2, 9.5),
    2: (1.4, 5.3, 7.1),
    4: (4.0, 6.5, 8.0),
    8: (2.0, 5.6, 7.4),
}
MARKERS = {
    '//': 0.75, '#': 0.55, '--': 0.8, '*/': 0.55,
    '>': 1.4, '>>': 0.75, '>>>': 0.75, '+': 0.65, '-': 0.42,
    '///': 3.5, '//!': 3.5,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        line, block, documentation, age, position = '', False, False, 1000, 0
    else:
        _, line, block, documentation, age, position = carry
    token = prefix.token_strings[-1]
    symbol = token.strip()
    star = symbol in {'*', '*\\'} and (token.startswith(' ') or block)
    pulse = 0.0
    if star or symbol in MARKERS:
        parts = re.split(r'\\[rn]', line)
        escaped = len(parts) > 1
        margin = parts[-1].lstrip('\\')
        numbered = bool(re.match(r'^\s*\d+\t', margin))
        margin = re.sub(r'^\s*\d+\t', '', margin)
        outer = ''
        if margin[:1] in {'+', '-'}:
            outer, margin = margin[0], margin[1:]
        if star and block and margin.startswith('//'):
            outer, margin = '//', margin[2:]
        if not margin.strip():
            if star:
                indent = len(margin)
                levels = STAR_INDENT.get(indent, (0.5, 4.8, 6.5))
                if '\t' in margin:
                    levels = (4.0, 7.0, 9.3)
                if numbered:
                    levels = (2.6, 4.5, 5.6)
                pulse = levels[1] if block else levels[0]
                fresh = math.exp(-max(0, age - 3) / 10.0)
                if block and documentation:
                    pulse += (levels[2] - levels[1]) * fresh
                    if position < 12 and indent == 0 and not numbered:
                        pulse += 2.0 * fresh
                if outer and indent == 0:
                    pulse *= 0.72 if outer == '+' else 0.5
                if escaped:
                    if block:
                        pulse *= 0.35 if indent == 0 else 0.85
                    else:
                        pulse *= 0.45
                if not token.startswith(' '):
                    pulse *= 0.5
                if '\r\n' in token:
                    pulse *= 0.65
                elif '\n' in token:
                    pulse *= 0.48
                if symbol == '*\\':
                    pulse *= 0.6
                if position == 0:
                    pulse = 0.31
            else:
                pulse = MARKERS[symbol]
                if symbol in {'-', '*/'} and not token.startswith(' '):
                    pulse = 0.0
                if token.startswith(' ') and symbol in {'+', '--'}:
                    pulse *= 0.4
                if '\n' in token and symbol != '*/':
                    pulse *= 0.5 if symbol.startswith('/') else 0.25
                pulse *= 0.65 if numbered else (0.55 if escaped else 1.0)
                if position == 0:
                    pulse = 0.0
    opening, closing = token.rfind('/*'), token.rfind('*/')
    if opening >= 0 or closing >= 0:
        block = opening > closing
        if block:
            documentation = token[opening:].startswith(('/**', '/*!'))
            age = 0
    line = (line + token).rsplit('\n', 1)[-1][-200:]
    state = (doc, line, block, documentation, age + 1, position + 1)
    return state, float(-pulse)

programs.luna:
"""Recognize line-leading comment, quote, and diff markers.

The component is usually quiet, but can send a strong negative signal on
comment decoration (especially the asterisks inside block comments)."""

READS = ()


def step(carry, prefix, upstream):
    text = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        in_block = False
        line_has_text = False
        previous = ""
    else:
        _, in_block, line_has_text, previous = carry

    # The line's first visible character, if this token contains one.
    segment = text.rsplit("\n", 1)[-1]
    if "\n" in text:
        line_has_text = False
    stripped = segment.lstrip(" \t\r")
    at_line_start = not line_has_text and bool(stripped)
    value = 0.0

    if at_line_start:
        if in_block and stripped.startswith("*"):
            value = -5.5
        elif stripped.startswith("//"):
            value = -0.9
        elif stripped.startswith("--"):
            value = -0.75
        elif stripped.startswith(">"):
            value = -1.0 if stripped.startswith(">>>") else -1.4
        elif stripped.startswith(("+", "-")):
            value = -0.75
        elif stripped.startswith("###"):
            value = -0.3
        elif stripped.startswith("#"):
            value = -0.45
        elif stripped.startswith("/*"):
            value = -0.15

    # Track ordinary C-style block comments, including across token boundaries.
    combined = previous + text
    i = 0
    while i + 1 < len(combined):
        pair = combined[i:i + 2]
        if not in_block and pair == "/*":
            in_block = True
            i += 2
        elif in_block and pair == "*/":
            in_block = False
            i += 2
        else:
            i += 1
    if text:
        previous = text[-1]
        for char in text:
            if char == "\n":
                line_has_text = False
            elif not char.isspace():
                line_has_text = True

    return (doc, in_block, line_has_text, previous), float(value)

programs.sol:
"""A lexical approximation to a text-output / diagnostic feature.

Printing and logging APIs receive strong negative predictions. String
formatting, command-line terms, and text-layout vocabulary receive weaker ones.
Dot-prefixed forms, capitalization, and familiar compounds refine these levels.
Other tokens are zero: smaller, idiosyncratic lexical responses are omitted.

Carry stores the preceding token and whether an earlier tool tag appeared.
Both reset at document boundaries. A token spelled "assistant" receives a
more negative prediction when a tool tag has appeared in the same document.
Numeric levels approximate the training activations of these word families;
this program is not a parser or a reconstruction of the model's internals.
"""

READS = ()

FAMILIES = (
    ({"stdout", "stderr", "stdlog"}, -2.5),
    ({"logging", "getlogger", "loggerfactory", "loglevel"}, -2.0),
    ({"endl", "ostream", "ostringstream", "fflush", "fputs"}, -1.9),
    ({"cout", "fmt", "stdio", "stringify", "tostring", "stringbuilder"}, -1.5),
    ({"string", "strings", "ansi"}, -1.2),
    ({"strcpy", "strcat", "strncpy", "strconv", "getstring", "fromstring"}, -0.9),
    ({"verbose", "verbosity", "traceback", "stacktrace", "dbg"}, -2.1),
    ({"debug", "debugging", "cli", "commandline"}, -1.65),
    ({"echo", "perror", "eslint", "lint", "linter"}, -1.0),
    ({"command", "commands", "cmd", "args", "argv", "argc", "kwargs"}, -0.65),
    ({"error", "errors", "warning", "warnings", "warn"}, -0.6),
    ({"parse", "parser", "parsed", "delimiter", "diagnostic", "msg"}, -0.7),
    ({"line", "whitespace", "braces", "indent", "comment", "doc", "docs"}, -0.5),
    ({"text", "txt", "input", "inputs", "stream"}, -0.3),
    ({"exception", "throw", "raise"}, -0.3),
    ({"inspect", "dump", "snippet", "readme", "documentation"}, -0.5),
    ({"editor", "diff", "exit", "syntax", "lexer", "parsing"}, -0.65),
    ({"terminal", "logs", "logged"}, -0.75),
    ({"readline", "iostream", "yaml", "markdown"}, -1.0),
    ({"dumps", "chalk"}, -1.5),
)
LEXICON = {word: value for words, value in FAMILIES for word in words}
PRINTF = {"printf", "sprintf", "fprintf", "snprintf", "vprintf", "vfprintf"}
LEVELS = {"info", "warn", "debug", "error", "trace", "verbose"}
FORMATTED_LEVELS = {level + "f" for level in LEVELS}


def response(token, previous):
    word = token.strip().lstrip("._-/(<[\"'")
    lower = word.lower()
    method = token.lstrip().startswith(".")
    spaced = token.startswith(" ")
    if lower in PRINTF:
        if lower in {"sprintf", "snprintf"}:
            return -2.55
        if lower in {"fprintf", "vfprintf"}:
            return -3.15
        return -3.45 if word[0].isupper() else -2.0
    if lower in {"println", "eprintln", "writeline"}:
        if not method:
            return -3.4
        return -2.35 if word == "Println" else -2.8
    if lower in {"print", "printstacktrace"}:
        if token.startswith("_"):
            return -3.0
        return -2.2 if method else -1.2
    if lower in {"prints", "printing", "printer"}:
        return -0.85
    if lower == "console":
        return -2.15 if word == lower else (-2.4 if spaced else -3.0)
    if lower == "logger":
        # Avoid treating the endings of blogger/vlogger as a logging API.
        return -0.3 if previous in {"b", "v"} else -1.9
    if lower == "log":
        if method:
            return -2.55 if "console" in previous.lower() else -1.3
        return -0.4
    if method and lower in LEVELS:
        return -1.0 if word[0].isupper() else -2.35
    if lower in FORMATTED_LEVELS:
        return -2.1 if lower == "errorf" else -3.2
    if method and lower == "out":
        return -2.05
    if lower in {"yaml", "markdown"} and method:
        return -0.15
    if lower == "report":
        return -0.15 if spaced else (-2.3 if method else -1.5)
    if lower == "formatter":
        return -3.0
    if lower in {"format", "formatted", "formatting"}:
        return -0.75 if spaced else -1.4
    if lower in {"output", "outputs"}:
        return -1.35
    if lower in {"message", "messages"}:
        return -1.8 if previous.strip().lower() == "error" else -0.8
    if lower == "info":
        return -3.1 if "debug" in previous.lower() else -0.7
    if lower == "line" and "command" in previous.lower():
        return -1.6
    if lower == "str":
        return -0.25 if word == "STR" else -0.65
    if lower == "err":
        return -0.3
    if word.endswith(("Error", "Exception", "Interrupt")):
        return -0.75
    if lower == "assert" or lower.startswith(
        ("assertequal", "asserttrue", "assertfalse", "assertthat")
    ):
        return -0.9
    if lower in {"options", "help"}:
        return -0.15 if spaced else -0.85
    if lower == "writer":
        return -1.15 if word[0].isupper() else -0.2
    if lower == "display":
        return -1.0 if word[0].isupper() and not spaced else -0.15
    if token.strip() == "<<":
        return -0.95
    if token == "(f" or token.startswith(" %"):
        return -0.3
    if token in {"输出", "打印"}:
        return -1.3
    return LEXICON.get(lower, 0.0)


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        previous, seen_tool = "", False
    else:
        _, previous, seen_tool = carry
    token = prefix.token_strings[-1]
    seen_tool = seen_tool or token in {"<tool_response>", "<tool_call>"}
    value = response(token, previous)
    if token == "assistant":
        value = -0.44 if seen_tool else -0.16
    return (doc, token, seen_tool), float(value)

programs.haiku:
"""Layer-0 MLP output feature: negative on words about printing, logging and console output.

The component's activation is near zero on almost every token. It goes clearly negative on
tokens that name output or messaging in code and chat: `print`, `println`, `printf`, `console`,
`stdout`, `cout`, `endl`, `output`, `string`; then logging and errors: `log`, `logger`, `error`,
`warn`, `message`, `format`, `info`; and more weakly on CLI and parsing words (`command`,
`parse`, `argparse`, `help`, `exit`) and on `err`, `str`, `out`, `line`.
The program predicts a fixed negative value per class of word and 0 elsewhere.
"""

READS = ()

# Words that name printing or console output (strongest).
OUTPUT_WORDS = {
    "print", "println", "printf", "fprintf", "console", "stdout", "stderr", "cout",
    "endl", "debug", "output", "outputs", "string", "prints", "infof",
}

# Words about logging, messages, errors and formatting (medium).
LOGGING_WORDS = {
    "log", "logger", "logging", "logs", "loglevel", "error", "errors", "warn", "warning",
    "message", "messages", "echo", "format", "formatted", "fmt", "tostring", "info", "trace",
    "perror", "inspect", "ostream", "stdio", "cli", "eslint", "lint", "command", "parse",
    "argparse", "help", "exit", "ignore",
}

# Words that are only sometimes about output (weak).
WEAK_WORDS = {"err", "str", "out", "std", "write", "line", "lines", "show", "assert", "parser", "tool", "diagnostics"}


def word(token):
    """The token as a bare lowercase word: no leading space, quote, dot or digit."""
    return "".join(ch for ch in token.lower() if "a" <= ch <= "z")


def step(carry, prefix, upstream):
    w = word(prefix.token_strings[-1])
    if w in OUTPUT_WORDS:
        return None, -1.5
    if w in LOGGING_WORDS:
        return None, -1.0
    if w in WEAK_WORDS:
        return None, -0.4
    return None, 0.0

programs.sol:
"""A detector of typographical repetition, mainly punctuation separators.

The negative response grows with the length of a repeated punctuation mark,
then usually weakens for very long runs. These short, interpolated curves
calibrate that response in activation units. Continuing the same separator
from the preceding token weakens it; newlines and comment wrappers also do.
Headings, code fences and documentation-comment stars are smaller responses.
Secondary responses cover standalone water/水 tokens and alphabet-order
character sequences. Most other lexical variation is deliberately omitted.
"""
import re

READS = ()
_RUN = re.compile(r'([^\w\s]|_)\1+')

# (run length, response magnitude), not a vocabulary or token-id table.
CURVES = {
    '=': ((2, 0.2), (3, 1.37), (4, 2.8), (8, 5.8), (12, 6.6),
          (15, 6.7), (16, 9.8), (32, 8.1), (64, 8.1), (80, 7.5)),
    '-': ((2, 0.0), (3, 0.29), (4, 0.63), (8, 2.2), (12, 4.1),
          (15, 4.0), (16, 5.7), (48, 6.7), (64, 4.8), (80, 4.6)),
    '*': ((2, 0.0), (3, 0.3), (4, 1.4), (8, 5.25), (16, 8.0),
          (24, 8.6), (32, 8.1), (64, 7.25), (80, 5.5)),
    '#': ((2, 0.16), (3, 0.35), (4, 0.44), (5, 0.7), (6, 1.27),
          (8, 5.15), (16, 8.0), (32, 8.9), (64, 7.1), (80, 6.3)),
    '_': ((2, 0.0), (4, 0.55), (8, 2.1), (12, 3.4), (16, 3.8),
          (32, 5.15), (64, 4.2)),
    '.': ((2, 0.0), (4, 0.0), (7, 0.35), (8, 1.85), (16, 2.5),
          (24, 3.6), (32, 4.1), (64, 4.1)),
    '/': ((2, 0.0), (3, 0.6), (4, 0.9), (8, 4.8), (16, 7.4),
          (32, 8.7), (64, 6.2), (80, 6.0)),
    '~': ((2, 0.27), (4, 1.65), (8, 4.05), (16, 6.3), (32, 7.35)),
    '+': ((2, 0.0), (3, 0.66), (4, 1.65), (8, 5.1), (16, 7.0),
          (32, 7.3)),
}


def magnitude(char, n):
    if char in CURVES:
        points = CURVES[char]
        for (a, x), (b, y) in zip(points, points[1:]):
            if n <= b:
                return x + (y - x) * (n - a) / (b - a)
        return points[-1][1]
    if char == '`':
        return 0.35 if n >= 3 else 0.0
    if char == '━':
        return min(5.0, 0.73 * n)
    if n < 4:
        return 0.0
    if char == '\\':
        return 0.6
    if char == '─':
        return min(6.0, 0.32 * (n - 2))
    if char in '█▬…':
        return min(5.0, 0.5 * (n - 1))
    if char in ',:':
        return min(4.0, 0.35 * (n - 2))
    if char == '?':
        return min(4.0, 0.5 * (n - 2))
    return min(4.0, 0.55 * (n - 1))


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        # Comment kind: 0 = none, 1 = block comment, 2 = documentation.
        comment, previous_mark, line_start = 0, '', True
    else:
        _, comment, previous_mark, line_start = carry
    s = prefix.token_strings[-1]
    text = s.strip()
    value, current_mark = -0.001, ''
    runs = list(_RUN.finditer(text))
    if runs:
        run = max(runs, key=lambda r: magnitude(r[1], len(r[0])))
        char, n = run[1], len(run[0])
        strength = magnitude(char, n)
        if n >= 4:
            current_mark = char
            if previous_mark == char:
                strength *= 0.75 if char == '=' else 0.65
            if text[:run.start()]:
                strength *= 0.8
            if text[run.end():]:
                strength *= 0.5
            if '\n' in s:
                strength *= 0.45 if char == '_' else 0.7
            if s.startswith(' '):
                if char in '-*' and n < 17:
                    strength += 0.7
                elif char == '.' and n >= 32:
                    strength *= 0.9
        elif char == '=' and s.startswith(' '):
            strength *= 0.66 if n == 3 else 0.5
        value = -strength
    if text.startswith('/**') and len(text) <= 6:
        value = -0.85 if s.startswith(' ') else -0.7
    elif text.startswith('**/'):
        value = -0.6
    elif text == '*' and s.startswith(' '):
        if comment == 2:
            value = -0.5 if line_start else -0.32
        elif comment == 1:
            value = -0.35 if line_start else -0.12
        else:
            value = -0.2 if line_start else 0.015
        if '\n' in s:
            value = -0.18
    elif text == '▬':
        value = -0.5
    elif text == '水':
        value = 1.5
    elif text.lower() == 'water':
        value = 0.25
    elif len(text) >= 10 and text.isascii() and text.isalpha():
        if all(ord(b) == ord(a) + 1 for a, b in zip(text, text[1:])):
            value = -1.1
    if '/*' in s:
        comment = 2 if '/**' in s else 1
    if '*/' in s:
        comment = 0
    line_piece = s.replace('\\n', '\n').rsplit('\n', 1)
    if len(line_piece) == 2:
        line_start = not line_piece[-1].strip()
    else:
        line_start = line_start and not s.strip()
    return (doc, comment, current_mark, line_start), float(value)

