"""A sparse text-surface predictor for separators, code markers, and water words."""

READS = ()

WATER_WORDS = {"water", "river", "nước", "水"}
REPEATED_SIGNS = "=#-_/.*^+"
ALPHABET = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"


def step(carry, prefix, upstream):
    """Mark visible divider/comment syntax and a small set of water terms."""
    token = prefix.token_strings[-1]
    word = token.strip()
    value = 0.0

    # Long runs of one punctuation mark act like visual dividers.
    if len(word) >= 3 and word[0] in REPEATED_SIGNS and word.count(word[0]) == len(word):
        sign, length = word[0], len(word)
        if sign == "=":
            value = -min(9.0, 0.55 * (length - 1))
        elif sign == "#":
            value = -0.11 * length if length < 7 else -min(6.0, 0.95 * (length - 3))
        elif sign == "-":
            if length == 3:
                value = -0.30
            elif length == 4:
                value = -0.82
            elif length >= 6:
                rate = 0.22 if length < 14 else 0.35
                value = -min(6.0, rate * length)
        elif sign == "/":
            rate = 0.20 if length < 8 else 0.46
            value = -min(7.4, rate * length)
        elif sign == "_" and length >= 8:
            value = -min(4.0, 0.12 * length)
        elif sign == "." and length >= 6:
            value = -min(1.1, 0.12 * length)
        elif sign == "*" and length >= 10:
            value = -min(7.5, 0.19 * length)
        elif sign == "^" and length >= 4:
            value = -0.40 * length
        elif sign == "+" and length >= 4:
            value = -0.42 * length

    # Repeated hash marks, fences, and documentation-comment openers.
    if word in ("##", "###", "####", "#####"):
        value = -0.30
    if token.lstrip().startswith("/**"):
        value = -0.78
    if word.startswith("```"):
        value = -0.40

    # Equality signs are also a common test-output divider.
    if word == "===":
        at_line_start = prefix.position == 0
        if prefix.position > 0:
            same_document = prefix.document_ids[-1] == prefix.document_ids[-2]
            at_line_start = not same_document
            if same_document:
                previous = prefix.token_strings[-2]
                at_line_start = previous.endswith(("\n", "\r"))
        value = -1.38 if at_line_start and token == word else -0.82

    # The whole alphabet is a recognizable printed sequence, not ordinary prose.
    if word == ALPHABET:
        value = -1.5

    # A modest positive prediction for observed water vocabulary in several languages.
    term = word.casefold()
    if term in WATER_WORDS:
        value = 1.4 if term == "水" else (0.45 if term == "nước" else 0.27)

    return None, float(value)

