    'rise': -1.95, 'rises': -1.75, 'rising': -2.15,
    'risen': -1.45, 'rose': -0.9,
    'trend': -0.95, 'trends': -1.07, 'trending': -1.65,
    'decline': -1.0, 'declines': -1.2, 'declined': -0.73,
    'declining': -1.0, 'collapse': -1.43, 'collapsed': -0.8,
    'surge': -1.2, 'swell': -1.0, 'swelling': -0.55,
    'rainfall': -0.7, 'inflation': -0.9, 'overflow': -0.65,
    'crash': -0.7, 'collision': -0.55, 'collisions': -0.3,
    'gain': -0.34, 'gains': -0.5, 'gained': -0.57, 'gaining': -1.0,
    'growth': -0.27, 'increase': -0.17, 'decrease': -0.27,
    'slope': -0.3, 'rapid': -0.45, 'motion': -0.24,
    'fluctuations': -0.4,
