TRANSLATIONS = {
    '记录': 2.2, '纪录': 2.2, '文档': 1.3, '窗口': 1.1,
    'документ': 1.5, 'dokument': 1.5, 'documento': 1.4,
    '跌': -5.0, '涨': -4.4, '漲': -3.2,
    '上涨': -3.7, '下跌': -3.2, '大涨': -2.5, '大跌': -2.7,
    '涨幅': -2.5, '跌幅': -2.1, '上升': -1.4, '下降': -1.55,
    '趋势': -0.75, '走势': -1.3, '落': -0.75, '崩': -1.4,
