WORD_VALUES = (RECORD_WORDS | DISPLAY_AND_STORAGE | PERSISTENCE_WORDS
               | MOTION_WORDS | TRANSLATIONS)


def word_form(token):
    return token.strip().lstrip('._/({[<\"\'`:-')


def lexical(token):
    form = word_form(token)
    word = form.lower()
    spaced = token.startswith(' ')
    value = WORD_VALUES.get(word, -0.003)
    if word == 'document' and not spaced:
        value = 2.75 if token[:1] in '.(\t' else 3.4
    elif word == 'documents' and form == 'Documents' and spaced:
        value = 2.35
    elif word == 'record' and token.startswith('.'):
        value = 1.8
    elif word == 'records' and form == 'Records' and spaced:
        value = 1.3
    elif word == 'window' and not spaced:
        value = 1.9
    elif word == 'windows' and form == 'Windows':
