                        'decline', 'increase', 'decrease', 'surge'}:
            value = -1.05
        elif previous in {'increases', 'decreases'}:
            value = -0.7
        elif previous in {'growth', 'trend', 'trends', 'shift', 'growing'}:
            value = -0.48
        elif previous in {'change', 'changes', 'reduction', 'drop'}:
            value = -0.3
    elif token == ' of':
        if previous in {'record', 'records', 'recording', 'fall',
                        'falls', 'rise', 'collapse', 'window'}:
