"""Word-continuation fragments (layers.0.mlp.down_proj:1521).

The component fires on tokens that are a fragment of a larger word or character rather
than the start of a new word. Read off the token text alone:

- a token that is only part of a UTF-8 character (it decodes to U+FFFD): strongest;
- a letter fragment with no leading space that follows another letter fragment or word
  ending, e.g. "ectomy" in "appendect|omy", "uro" in "Art|uro": medium, larger for
  fragments of 3+ characters, smaller for 2-character ones;
- a letter fragment after punctuation or a space: weak;
- word starts (leading space), punctuation, digits and whitespace: 0.

Numbers are the activation scale of the component (mean ~0.04, RMS ~0.2).
"""
READS = ()

PARTIAL_CHARACTER = 0.55  # token is part of a multi-byte character
FRAGMENT_AFTER_LETTERS = 0.20  # letter fragment of 3+ chars continuing a word
SHORT_FRAGMENT = 0.10  # letter fragment of 2 chars continuing a word
FRAGMENT_AFTER_OTHER = 0.05  # letter fragment after punctuation, digit or space


def _is_letters(s):
    return bool(s) and all(c.isalpha() for c in s)


def step(carry, prefix, upstream):
    toks = prefix.token_strings
    t = toks[-1]
    if "�" in t:
        return carry, PARTIAL_CHARACTER
    if len(t) < 2 or not _is_letters(t):
        return carry, 0.0
    same_doc = len(toks) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = toks[-2] if same_doc else ""
    if prev and prev[-1].isalpha():
        return carry, FRAGMENT_AFTER_LETTERS if len(t) >= 3 else SHORT_FRAGMENT
    return carry, FRAGMENT_AFTER_OTHER

