READS = ()
DEFINING = {
    'define', 'defining', 'suppose', 'initialize',
    'setting', 'settings', 'setup',
}


def step(carry, prefix, upstream):
    document = prefix.document_ids[-1]
    if carry is None or carry[0] != document:
        position, previous = 0, ''
    else:
        position, previous = carry[1] + 1, carry[2]
    token = prefix.token_strings[-1]
    word = token.strip()
    lower = word.lower()
    inside_word = bool(previous) and (
        previous[-1].isalnum() or previous[-1] == '_'
    )
    indentation = previous.isspace() and len(previous) > 1
    value = 0.0

    if lower == 'let':
        if word == 'Let':
            value = 6.3 - 0.18 * math.log1p(position)
            if position == 0:
                value = 7.5 if token.startswith(' ') else 8.4
        elif word == 'LET':
            value = 2.1 if inside_word and token == word else 4.9
        elif token.startswith(' '):
            value = 6.0 - 0.11 * math.log1p(position)
            if indentation:
                value -= 0.56
            if position == 0:
                value = 7.6
        elif token.startswith('\t'):
            value = 7.0 if position == 0 else 4.8
        else:
            value = 6.9 if position == 0 else (3.6 if inside_word else 5.4)
    elif lower == '(let':
        value = 4.5
    elif lower == 'lets':
        value = 3.5 if token.startswith(' ') else 2.8
    elif lower == 'letting':
        value = 4.2
    # Chinese: let/make, cause, suppose, by, call, make/use.
    elif word in {'让', '讓'}:
        value = 3.0
    elif word.startswith(('让', '讓')):
        value = 1.8 if word.endswith('你') else 2.2
    elif word == '令':
        value = 2.4
    elif word == '令人':
        value = 1.3
    elif word in {'设', '設'}:
        value = 1.6
    elif word == '由':
        value = 1.2
    elif word == '叫':
        value = 0.95
    elif word in {'使', '用'}:
        value = 0.7
    elif lower == 'denote':
        value = 1.7
    elif lower.lstrip('#') in DEFINING:
        value = 0.9 if word in {'Define', 'Initialize'} else 0.6
    elif lower.lstrip('(_') == 'var':
        value = 0.8
    elif lower.lstrip('(_') == 'const':
        value = 0.45
    elif word == 'mut':
        value = 0.3

    if previous.strip().lower() == 'let' and word in {"'s", '’s'}:
        value = 0.7

    return (document, position, token), float(value)

