        'construct', 'constructed', 'constructing', 'constructive',
        'reconstruction', 'implementation', 'administration'
    }:
        return -0.27
    if w in {'secret', 'secrets', 'secretary', 'soul', 'souls'}:
        return 0.27
    if token in {'施工', '施工现场'}:
        return -2.07
    if token == '工地':
        return -1.48
    if token in {'建设', '建設', '建筑', '建築', '建造', '建设工程'}:
        return -0.70
    if token in {'施', '实施', '實施', '施行'}:
        return -0.58 if token == '施' else -0.33
    if token == '素':
        return 1.10
    return -0.0026


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    same_document = carry is not None and carry[0] == doc
    previous = carry[1] if same_document else ''
    construction = carry[2] if same_document else False
    token = prefix.token_strings[-1]
    word = token.strip().lstrip('._(')
    value = response(token, previous)
    if token == '工' or '\ufffd' in token:
        ending = prefix.text_prefixes[-1][-2:] if same_document else token[-2:]
        if token == '工' and same_document and ending == '施工':
            value = -2.07
        elif '\ufffd' in token and ending.endswith('素'):
            value = 1.10
        elif '\ufffd' in token and ending.endswith('施'):
            value = -1.0
    if construction and word.lower() in {
        'of', 'on', 'in', 'site', 'workers', 'projects'
    }:
        value -= 0.28
    construction = word.lower() in {'construction', 'constructions'} and value < -1
    return (doc, word, construction), float(value)

programs.haiku:
"""Layer-0 MLP feature for one rank-one piece of down_proj (component 1529).

What it does: it is silent almost everywhere, and goes strongly negative on the word
"construction" (and 施工, the Chinese for construction work), moderately negative on
other words for building and construction (建设, 建筑, стр- as in строительство,
constructor/builder), and mildly positive on the character 素 (plain / element, as in
酵素 enzyme or 素人 amateur). Nothing else is modelled; the diffuse small values
elsewhere are predicted as 0.
"""

READS = ()

CONSTRUCTION = {"construction", "Construction", " construction", " Construction"}
BUILD_ZH_RU = {"施工", "建设", "建筑", "建設", "стр", "建设工程"}
BUILDERS = {"constructor", "constructors", "builder", "Builder", "constr"}
PLAIN = {"素"}


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1].strip()
    if tok in CONSTRUCTION:
        value = -2.0
    elif tok in BUILD_ZH_RU:
