"""A mostly lexical icon feature, with a few weaker spelling responses.

Icon(s), including punctuation-prefixed identifiers, produces a large
positive value. It is stronger after a quote or path separator, and weaker
when the same token follows sil/il, lex, or a few other word fragments. Icon
compound names, visual-symbol words, and short ico/co fragments produce
smaller values. A few summary/intent words produce negative values.
Everything else is zero; state stores only the preceding token and document.
"""
READS = ()

# Ordinary visual-symbol and interface vocabulary, not token-id lookups.
VISUAL_WORDS = {
    'logo': 0.46, 'emblem': 0.5, 'avatar': 0.25,
    'thumbnail': 0.4, 'shortcut': 0.75, 'menu': 0.3,
    '图标': 2.35, '商标': 0.44,
}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    first = carry is None or carry[0] != doc
    previous = '' if first else carry[1]
    text = raw.strip()
    word = text.lstrip("._-/'(\"")
    low = word.lower()

    if low in {'icon', 'icons'}:
        value = 4.4 if low == 'icon' else 4.2
        if word[0].isupper():
            value += 0.2 if low == 'icon' else 0.5
        if raw == 'icon':
            before = previous.strip().lower()
            if before.endswith(('sil', 'il')):
                value = 1.6
            elif before.endswith('lex'):
                value = 2.6
            elif before in {'sem', 'r', 'd', 'qu'}:
                value = 3.7
            elif previous.endswith(('"', "'", '/')):
                value = 5.1
            elif previous.endswith('.'):
                value = 4.8
        if first:
            value = 4.0 if word[0].isupper() else 3.5
            if raw == 'icon':
                value = 3.85
    elif word.endswith('Icon'):
        value = 3.2 if word == 'setIcon' else 1.4
    elif low.startswith('icon') and len(word) > 4 and word[4].isupper():
        value = 0.9 if low == 'iconbutton' else 2.3
    elif low in {'favicon', 'avicon', 'glyphicon', 'lyphicon'}:
        value = 1.0
    elif low in {'icone', 'icont'}:
        value = 1.65
    elif low in VISUAL_WORDS:
        value = VISUAL_WORDS[low]
    elif low == 'con':
        value = 0.29 if text.isupper() else 0.12
    elif text == 'ico':
        value = 0.42
    elif text in {'icol', 'icolor', 'icot', 'ICO', 'iko', 'aco'}:
        value = 0.55
    elif text in {'iconic', 'ikon', 'icom'}:
        value = 1.0
    elif text in {'incon', 'acon', 'uncon', 'descon', 'reconoc'}:
        value = 1.08
    elif text in {'recon', 'econ', 'Recon'}:
        value = 1.48
    elif text in {'decom', 'recom', 'Decom', 'Decomp', 'acom', 'ecom'}:
        value = 0.85
    elif text in {'ircon', 'miscon', 'inconvenience'}:
        value = 0.64
    elif low == 'therefore':
        value = -0.55 if raw == 'Therefore' else -0.48
        if text[0].islower():
            value = -0.33
    elif low in {'overall', 'generally', 'purpose', 'purposes'}:
        value = -0.2 if low == 'purposes' else -0.3
    else:
        value = 0.0
    return (doc, raw), value

programs.haiku:
"""Layer 0, MLP down-projection, component 1531: an "icon" detector.

The component reads the current token and writes a large value into the residual stream
when that token is the word "icon", in any spelling the tokenizer produces: " icon",
"Icon", "icons", "ICON", ".icon", "/icon", "_icon". It responds more weakly to words
built around "icon" ("setIcon", "ImageIcon", "iconName", "iconic"), more weakly still to
graphics and asset words (logo, avatar, svg, favicon, emoji, badge, sprite, ico), and a
little to word pieces that spell "-econ" or "-con" ("recon", "econ", "decom", "incon").
"silicon" and "semiconductor" do not count. A few essay-style words ("Therefore",
"overall", "generally", "purpose") push it slightly negative. Everything else is about
zero, so the program is a word lookup: it uses no context and no carried state.
"""

import re

READS = ()

GRAPHICS = {
    "logo", "avatar", "svg", "favicon", "glyph", "glyphicon", "emoji", "symbol",
    "badge", "bitmap", "shortcut", "fontawesome", "mdi", "sprite", "thumbnail",
    "drawable", "uiimage", "ico",
}  # fmt: skip
FRAGMENTS = {"econ", "recon", "decom", "recom", "incon", "acon", "uncon", "descon", "miscon"}
SOFT_NEGATIVE = {"therefore", "overall", "generally", "purpose"}


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    letters = re.sub(r"[^a-z]", "", word)
    if letters in ("icon", "icons"):
        value = 4.0
    elif "icon" in word and "silic" not in word and "semicon" not in word:
        value = 1.0 if letters.startswith("iconic") else 2.0
    elif word in GRAPHICS:
        value = 0.4
    elif word in FRAGMENTS:
        value = 1.0
    elif word in SOFT_NEGATIVE:
        value = -0.4
    else:
        value = 0.0
    return carry, value

programs.luna:
"""A sparse spelling rule: the tokens “icon” and “icons” trigger a large
positive value, other icon-containing words a smaller one, and “therefore” a
negative value. All other tokens are predicted as quiet."""

READS = ()


def step(carry, prefix, upstream):
    token = prefix.token_strings[-1].strip().lower()
    if token in ("icon", "icons"):
        return None, 4.5
    if token == "therefore":
        return None, -0.52
    if "icon" in token:
        return None, 1.1
    return None, 0.0

programs.haiku:
"""Layer-0 MLP down-projection component 1532: a negative "new noun phrase" detector.

The component is switched by the word before a determiner. It goes strongly negative on
"the" or a possessive ("his", "its", "your", "our", "their", "my", "her") that opens a new
clause or noun phrase: after punctuation, after a clause-linking word ("that", "if",
"when", "and", "but", "so"), or at a sentence start. The possessives are about 1.4 times as
strong as "the". After "of", "in", "on", "to", "is" it stays near zero, and after a place
or motion preposition ("into", "from", "across", "during") it is mildly positive. The
indefinite "a", "an", "this", "these", "every" barely respond, so they get a small weight.
"""
READS = ()

POSSESSIVE = {"his", "her", "its", "your", "our", "their", "my"}
DEFINITE = {"the"}
INDEFINITE = {"a", "an", "this", "these", "those", "every"}
OPEN_PUNCT = {",", ";", ":", "(", "[", '"', "“", "'", "—", "-", "*"}
CLAUSE_LINK = {
    "and", "but", "or", "so", "if", "when", "while", "that", "because", "since",
    "unless", "then", "until", "where", "which", "what", "how", "whether", "though",
    "although", "perhaps", "maybe", "once", "as", "than",
}
SENTENCE_END = {".", "!", "?", "\n", "\n\n", ").", "].", "<|endoftext|>"}
PLACE_PREP = {
    "from", "into", "across", "within", "during", "through", "along", "throughout",
    "inside", "near", "outside", "among", "around", "against", "onto", "towards", "upon",
}
OF_IN_ON = {"of", "in", "on", "to", "at", "for", "with", "by", "is", "was", "are", "be"}


def _value(prev):
    """Activation for a plain definite determiner ("the"), by the word before it."""
    if prev == "" or prev.endswith(("\n", ".", "!", "?")):
        return -1.4
    if prev in OPEN_PUNCT or prev.endswith(","):
        return -2.3
    if prev in CLAUSE_LINK:
        return -1.8
    if prev in PLACE_PREP:
        return 0.35
    if prev in OF_IN_ON:
        return 0.0
    return -0.45  # verbs, adverbs and other words


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().lower()
    if word in POSSESSIVE:
        scale = 1.4
    elif word in DEFINITE:
        scale = 1.0
    elif word in INDEFINITE:
        scale = 0.15
    else:
        return None, 0.0
    if len(prefix.token_ids) < 2 or prefix.document_ids[-2] != prefix.document_ids[-1]:
        return None, scale * -1.4
    prev = prefix.token_strings[-2].strip()
    return None, scale * _value(prev)

programs.sol:
"""Lexical 'no', mental acts, uncertainty, and acknowledgements.

Assign fitted responses to a small vocabulary of ordinary words.  A
preceding 'me', 'us', or apostrophe-s boosts mental acts as a simple cue
for invitations like 'let me see'; 'I' boosts selected self-reports.
Distinguish 'not sure', 'make sure', and 'thank you'.  Case, continuation
of an existing word, and a few Romance function words refine the lexical
rules.  All other tokens receive zero.  Remember only the previous token,
and reset that memory when the document changes.

This captures the dominant lexical/phrase responses, not the smaller,
diffuse responses to many other tokens.
"""

READS = ()

# Present-tense mental acts, discourse markers, and their common inflections.
MENTAL = {
    'see': 1.05, 'think': 0.85, 'know': 0.27,
    'remember': 0.65, 'recall': 0.65, 'understand': 0.08,
    'check': 0.34, 'try': 0.12, 'look': 0.12,
    'notice': 0.28, 'believe': 0.22, 'suppose': 0.25,
    'guess': 0.20, 'wonder': 0.22, 'hear': 0.35,
    'hope': 0.55, 'forget': 0.32,
    'seen': 0.42, 'saw': 0.44, 'seeing': 0.90,
    'thought': 0.41, 'thinking': 0.35, 'thinks': 0.27,
    'looking': 0.18, 'checking': 0.33, 'checked': 0.26,
    'noticed': 0.28, 'waiting': 0.39, 'await': 0.29,
}
DISCOURSE = {
    'maybe': 0.75, 'perhaps': 0.67, 'probably': 0.27,
    'possibly': 0.19, 'actually': 0.50, 'hmm': 0.52,
    'perfect': 0.64, 'yes': 0.27, 'okay': 0.28,
    'sorry': 1.05, 'thanks': 0.76, 'thank': 0.36,
}
INVITATION = {
    'see': 2.05, 'think': 1.20, 'know': 1.03,
    'check': 0.54, 'try': 0.68, 'look': 0.64,
    'understand': 0.38, 'remember': 0.50,
    'recall': 0.50, 'guess': 0.35,
}


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or carry[0] != doc:
        prev, last = '', ''
    else:
        prev, last = carry[1:]
    token = prefix.token_strings[-1]
    word = token.strip().strip('_/-."`([“').lower()
    continuation = (not token[:1].isspace() and last[-1:].isalpha())
    value = MENTAL.get(word, DISCOURSE.get(word, 0.0))
    if word == 'see':
        if token == 'See':
            value = 1.76
        elif token.strip() == 'See' or token == 'see':
            value = 0.45 if continuation else 1.47
        elif prev == 'please':
            value = 2.05
    if word == 'no':
        value = 0.79 if token.strip() == 'NO' else 1.10
        if token == 'no':
            value = 0.35 if continuation else 1.10
        elif token == 'No':
            value = 1.02
        if token.startswith('_'):
            value = 0.69
        if prev == 'wait':
            value += 0.40
        elif prev in {'que', 'pero', 'de', 'y', 'che', 'di'}:
            value = 0.48
    elif word == 'wait':
        value = 0.96 if token == ' Wait' else 0.77
        if token == ' wait':
            value = 0.62
    elif word == 'sure':
        value = 0.50
        if prev in {'not', "n't"}:
            value = 1.70
        elif prev in {'make', 'making', 'made'}:
            value = 0.39
        elif prev in {"'m", '’m', 'am', 'quite'}:
            value = 1.08
    elif word == 'you' and prev == 'thank':
        value = 0.72
    if word in INVITATION:
        if prev in {'me', 'us'}:
            value += INVITATION[word]
        elif prev in {"'s", '’s'}:
            value += 0.87 * INVITATION[word]
        elif prev == 'i':
            value += {'see': 0.30, 'think': 0.30,
                      'know': 0.18, 'understand': 0.33}.get(word, 0.0)
    return (doc, word, token), float(value)

