"""Draft 4: deliberation words (self-talk such as "Let me see", "Not sure", "Wait, no")."""
READS = ()

HEDGES = {"wait": 0.8, "perhaps": 0.7, "maybe": 0.8, "hmm": 0.5, "actually": 0.5,
          "remember": 0.7, "sorry": 1.1, "thanks": 1.0, "thank": 0.5, "hope": 0.5,
          "believe": 0.5, "recall": 0.5, "notice": 0.5, "perfect": 0.6, "okay": 0.4,
          "understand": 0.5, "hear": 0.5, "suppose": 0.4}
SEE = {"see": 1.0, "seeing": 0.9, "seen": 0.4, "saw": 0.4, "think": 1.0, "thinking": 0.4,
       "thought": 0.4, "know": 0.3}
AFTER_LET_ME = {"see": 3.0, "think": 2.2, "know": 1.3, "check": 0.9, "try": 0.8,
                "look": 0.7, "consider": 0.5}


def step(carry, prefix, upstream):
    raw = prefix.token_strings[-1]
    word = raw.strip().lower()
    prev = ""
    prev_raw = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev_raw = prefix.token_strings[-2]
        prev = prev_raw.strip().lower()
    if word == "no":
        # "no" as a word of its own (not inside a longer word such as "noivado")
        word_start = raw[:1] == " " or not prev_raw[-1:].isalnum()
        value = 1.15 if word_start else 0.3
    elif word == "sure":
        value = 1.6 if prev == "not" else 0.4
    elif prev in ("me", "us", "'s") and word in AFTER_LET_ME:
        value = AFTER_LET_ME[word]
    elif word in SEE:
        value = SEE[word]
    elif word in HEDGES:
        value = HEDGES[word]
    else:
        value = 0.0
    return carry, float(value)

programs.luna:
"""Highlight brief words that express a stance or invite reflection.

Negative answers, conversational pauses, hedges and words of knowing or
perception receive a positive estimate; unrelated tokens receive zero.
"""
READS = ()

NEGATION = frozenset({"no"})
REFLECTION = frozenset({
    "know", "think", "remember", "understand", "see", "saw", "look",
})
STANCE = frozenset({"maybe", "perhaps", "wait", "perfect", "you"})


def step(carry, prefix, upstream):
    word = prefix.token_strings[-1].strip().strip(".,!?;:'\"()[]{}_ ").casefold()
    if word in NEGATION:
        return None, 0.8
    if word in REFLECTION:
        return None, 0.6
    if word in STANCE:
        return None, 0.6
    return None, 0.0
